// Kontakty: seznamy, detail s 9 záložkami, editace, sdílení, předání, odvolání souhlasu.
const ownerOthers=c=>[...new Set([...(c.managers||[]),...(c.sharedWith||[])])].filter(x=>x!==c.owner);
const ownerCell=c=>{const n=ownerOthers(c).length;return `<button class="who-btn" data-a="owners" data-id="${c.id}" aria-haspopup="dialog" aria-label="Správci kontaktu: ${esc(shortName(c.owner))}${n?' a další '+n:''}">${av(c.owner)}<span>${esc(shortName(c.owner))}</span>${n?`<span class="av-more">+${n}</span>`:''}</button>`;};
const COLS=[['status','Stav'],['rel','Vztah'],['rating','Hodnocení'],['act','Aktivita'],['called','Voláno'],['owner','Správce'],['phone','Telefon'],['tags','Štítky'],['city','Město'],['email','E-mail']];
const ccols=()=>COLS.filter(x=>x[0]!=='rating'||rateOn());
const DEF_COLS=['status','rel','rating','act','owner','phone','tags'];
const listKey=t=>'list-'+t;
const listState=t=>ui(listKey(t),{q:'',sort:t==='osoby'?'lastSort':'name',dir:1,page:0,size:24,sel:[],open:false,f:{status:'',rel:'',called:'',owner:'',tag:'',shared:false},cols:[...DEF_COLS]});
const sortVal=(c,k)=>k==='called'?(c.called||''):k==='lastSort'?(c.last||c.name)+' '+(c.first||''):k==='firstSort'?(c.first||c.name)+' '+(c.last||''):k==='owner'?shortName(c.owner):k==='tags'?(c.tags[0]||''):c[k];
const normStr=s=>String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();

function filtered(t){const s=listState(t),ty=t==='osoby'?'osoba':'organizace',q=normStr(s.q);
  let r=DB.contacts.filter(c=>c.type===ty&&c.active);
  if(q)r=r.filter(c=>normStr(c.name+' '+c.phone+' '+c.email+' '+c.city+' '+c.tags.join(' ')).includes(q));
  const f=s.f;if(f.status)r=r.filter(c=>c.status===f.status);if(f.rel)r=r.filter(c=>c.rel===f.rel);if(f.called)r=r.filter(c=>f.called==='Nevoláno'?!c.called:c.callRes===f.called);if(f.owner)r=r.filter(c=>c.owner===f.owner||(c.managers||[]).includes(f.owner));if(f.tag)r=r.filter(c=>c.tags.includes(f.tag));if(f.shared)r=r.filter(c=>(c.sharedWith||[]).includes(ME));
  return r.sort((a,b)=>{const x=sortVal(a,s.sort),y=sortVal(b,s.sort);return s.dir*(typeof x==='number'?x-y:csSort(x,y));});}
function viewContactList(t){
  const s=listState(t),all=filtered(t),pages=Math.max(1,Math.ceil(all.length/s.size));if(s.page>=pages)s.page=pages-1;
  const rows=all.slice(s.page*s.size,(s.page+1)*s.size);const isP=t==='osoby';
  const head=(k,l,sk=k)=>`<th class="sort" data-a="sortc" data-t="${t}" data-k="${sk}">${l}${s.sort===sk?ic(s.dir>0?'arrow-up-2':'arrow-down','s16'):''}</th>`;
  const colTh=ccols().filter(c=>s.cols.includes(c[0])).map(c=>c[0]==='rating'?head(c[0],c[1]).replace('class="sort"','class="sort ctr"'):head(c[0],c[1])).join('');
  const f=s.f,chips=[];const lab={status:'Stav',rel:'Vztah',called:'Voláno',owner:'Správce',tag:'Štítek'};
  Object.keys(lab).forEach(k=>{if(f[k])chips.push(`<span class="chip">${lab[k]}: ${esc(k==='owner'?shortName(f[k]):f[k])}<button data-a="clearf" data-t="${t}" data-k="${k}" aria-label="Zrušit filtr">×</button></span>`);});
  if(f.shared)chips.push(`<span class="chip">Jen sdílené se mnou<button data-a="clearf" data-t="${t}" data-k="shared" aria-label="Zrušit filtr">×</button></span>`);
  const fc=chips.length;
  const panel=s.open?`<div class="filters"><div class="field"><label>Stav</label>${sel('fstatus','status',['',...DB.settings.statuses],f.status,t)}</div><div class="field"><label>Vztah</label>${sel('frel','rel',['','Odběratel','Partner','Dodavatel','Konkurent'],f.rel,t)}</div><div class="field"><label>Voláno</label>${sel('fcalled','called',['','Nevoláno',...CALL_RES],f.called,t)}</div><div class="field"><label>Správce</label>${sel('fowner','owner',['',...DB.users.filter(u=>u.state==='Aktivní').map(u=>u.id)],f.owner,t,v=>v?shortName(v):'Všichni')}</div><div class="field"><label>Štítek</label>${sel('ftag','tag',['',...DB.settings.tags],f.tag,t)}</div>${isP?`<label class="row" style="height:40px"><input type="checkbox" class="cb" data-a="fshared" data-t="${t}" ${f.shared?'checked':''}>Jen sdílené se mnou</label>`:'<span></span>'}</div>`:'';
  const cell=(c,k)=>{switch(k){case 'status':return statusDot(c.status);case 'called':return c.called?`<span class="row">${fmt(c.called)}${c.callRes?`<span class="badge ${({'Dovoláno':'b-grn','Schůzka':'b-grn','Později':'b-amb','Nedostupný':'','Odmítnuto':'b-red'})[c.callRes]}">${c.callRes}</span>`:''}</span>`:'<span class="mute">Nevoláno</span>';case 'rating':return rating(c.rating);case 'act':return `<span class="row">${actIcon(c.actType)}${fmt(c.act)}</span>`;case 'owner':return ownerCell(c);case 'phone':return `<a data-a="call" data-v="${esc(c.phone)}" data-n="${esc(c.name)}">${esc(c.phone)}</a>`;case 'email':return c.email?`<a href="mailto:${esc(c.email)}">${esc(c.email)}</a>`:'<span class="mute">—</span>';case 'tags':return `<span class="row"><span class="chip">${esc(c.tags[0]||'')}</span>${c.tags.length>1?`<span class="small mute" data-tip="${esc(c.tags.slice(1).join(', '))}">+${c.tags.length-1}</span>`:''}</span>`;default:return esc(c[k]);}};
    const body=rows.map(c=>`<tr class="${s.sel.includes(c.id)?'sel':''}" data-go="#/kontakt/${c.id}/zakladni"><td style="width:48px"><input type="checkbox" class="cb" data-a="selc" data-t="${t}" data-id="${c.id}" aria-label="Vybrat ${esc(c.name)}" ${s.sel.includes(c.id)?'checked':''}></td><td class="c-name"><span class="row med">${isP?'':ic('buildings','s16')}${esc(c.name)}</span></td>${ccols().filter(x=>s.cols.includes(x[0])).map(x=>`<td data-k="${x[0]}"${x[0]==='rating'?' class="ctr"':''}>${cell(c,x[0])}</td>`).join('')}<td style="width:48px"><button class="more" data-a="crow" data-id="${c.id}" aria-label="Další akce">${ic('more','s16')}</button></td></tr>`).join('');
  const allSel=rows.length&&rows.every(c=>s.sel.includes(c.id)),someSel=rows.some(c=>s.sel.includes(c.id));
  const html=`<div class="crumbs"><a href="#/kontakty/osoby">Kontakty</a><span>/</span>${isP?'Osoby':'Organizace'}</div>
   <div class="page-head list-h">${ic(isP?'user':'buildings','s32')}<h1>${isP?'Osoby':'Organizace'}</h1><div class="acts"><input class="inp" style="width:240px;height:32px" placeholder="Hledat v seznamu" value="${esc(s.q)}" data-input="listq" data-t="${t}" id="lq"><button class="btn ${s.open?'pri':''}" data-a="fopen" data-t="${t}">${ic('filter','s16')}Filtry${fc?` (${fc})`:''}</button><button class="btn" data-a="exportc" data-t="${t}">${ic('export','s16')}Export</button><a class="btn pri fab" href="#/kontakt/novy-${isP?'osoba':'organizace'}/upravit">${ic('add','s16')}Přidat kontakt</a></div></div>
   ${panel}${fc?`<div class="act-chips">${chips.join('')}<a data-a="clearall" data-t="${t}" class="small">Zrušit vše</a></div>`:''}
   ${s.sel.length?`<div class="bulk"><b class="sb">Vybráno: ${s.sel.length}</b><span class="spacer"></span><button class="btn bulk-main" data-a="bulkmenu" data-t="${t}" aria-haspopup="dialog">${ic('task-square','s16')}Hromadné akce</button><button class="btn bulk-main" data-a="bulkclear" data-t="${t}">Zrušit výběr</button></div>`:''}
   <div class="tbl-card">${all.length?`<table class="tbl frozen"><thead><tr><th><input type="checkbox" class="cb ${someSel&&!allSel?'ind':''}" data-a="selall" data-t="${t}" aria-label="Vybrat vše na stránce" ${allSel?'checked':''}></th>${isP?nameHead('sortname',s,t):head('name','Název')}${colTh}<th><button class="more" data-a="colsopen" data-t="${t}" aria-label="Sloupce tabulky" data-tip="Sloupce tabulky">${ic('setting-2','s16')}</button></th></tr></thead><tbody>${body}</tbody></table>`:`<div class="empty">${ic('search-normal')}<h3>Nic jsme nenašli</h3><button class="btn" data-a="clearall" data-t="${t}">Zrušit filtry</button></div>`}</div>`;
  return {nav:t==='osoby'?'osoby':'firmy',html,foot:footer(listKey(t),rows.length,all.length,pages),after:()=>{if(UI._focusq){const i=document.getElementById('lq');if(i){i.focus();i.setSelectionRange(i.value.length,i.value.length);}UI._focusq=false;}}};
}
const sel=(a,k,opts,v,t,lab)=>`<select class="inp" data-a="fset" data-on="change" data-k="${k}" data-t="${t}" aria-label="${k}">${opts.map(o=>`<option value="${o}" ${o===v?'selected':''}>${lab?lab(o):(o||'Všechny')}</option>`).join('')}</select>`;
ACT.sortname=el=>{const s=listState(el.dataset.t);sortMenu(el,s);};
ACT.statusmenu=el=>{const c=contact(el.dataset.id);openMenu(el,DB.settings.statuses.map(st=>({t:st,ic:c.status===st?'tick-circle':null,fn:()=>{const old=c.status;if(old===st)return;c.status=st;ensure(c);addHistory(c,'Stav',`Změnil stav z „${old}“ na „${st}“.`);save();toast('Stav: '+st,()=>{c.status=old;save();});render();}})),200);const pp=layer().querySelector('.pop');if(pp)pp.style.left=el.getBoundingClientRect().left+'px';};
ACT.sortc=el=>{const s=listState(el.dataset.t),k=el.dataset.k;if(s.sort===k)s.dir*=-1;else{s.sort=k;s.dir=1;}s.page=0;render();};
ACT.fopen=el=>{const s=listState(el.dataset.t);s.open=!s.open;render();};
ACT.fset=el=>{const s=listState(el.dataset.t);s.f[el.dataset.k]=el.value;s.page=0;render();};
ACT.fshared=el=>{const s=listState(el.dataset.t);s.f.shared=el.checked;s.page=0;render();};
ACT.clearf=el=>{const s=listState(el.dataset.t);s.f[el.dataset.k]=el.dataset.k==='shared'?false:'';render();};
ACT.clearall=el=>{const s=listState(el.dataset.t);s.f={status:'',rel:'',called:'',owner:'',tag:'',shared:false};s.q='';render();};
ACT.listq=el=>{const s=listState(el.dataset.t);s.q=el.value;s.page=0;UI._focusq=true;clearTimeout(UI._qt);UI._qt=setTimeout(render,180);};
ACT.selc=el=>{const s=listState(el.dataset.t),id=el.dataset.id;s.sel=el.checked?[...s.sel,id]:s.sel.filter(x=>x!==id);render();};
ACT.selall=el=>{const t=el.dataset.t,s=listState(t),a=filtered(t).slice(s.page*s.size,(s.page+1)*s.size).map(c=>c.id);s.sel=el.checked?[...new Set([...s.sel,...a])]:s.sel.filter(x=>!a.includes(x));render();};
ACT.bulkclear=el=>{listState(el.dataset.t).sel=[];render();};
ACT.colsopen=el=>{const t=el.dataset.t,s=listState(t);popover(el,`<div class="sb" style="padding:8px">Sloupce tabulky</div><label class="row" style="padding:4px 8px;color:var(--n500)"><input type="checkbox" class="cb" checked disabled>${t==='osoby'?'Jméno':'Název'} (ukotveno)</label>${ccols().map(c=>`<label class="row" style="padding:4px 8px"><input type="checkbox" class="cb" data-a="coltog" data-t="${t}" data-k="${c[0]}" ${s.cols.includes(c[0])?'checked':''}>${c[1]}</label>`).join('')}<hr><button class="it" data-a="colreset" data-t="${t}">${ic('refresh','s16')}Obnovit výchozí</button>`,240);};
ACT.coltog=el=>{const s=listState(el.dataset.t),k=el.dataset.k;s.cols=el.checked?[...s.cols,k]:s.cols.filter(x=>x!==k);const pa=document.getElementById('app');const r=route(routeNow);pa.innerHTML=shell(r.html,r.nav,r.foot);};
ACT.colreset=el=>{listState(el.dataset.t).cols=[...DEF_COLS];render();};
ACT.crow=(el)=>{const c=contact(el.dataset.id);openMenu(el,[{t:'Otevřít kontakt',ic:'eye',fn:()=>go(`#/kontakt/${c.id}/zakladni`)},{t:'Upravit',ic:'edit-2',fn:()=>go(`#/kontakt/${c.id}/upravit/zakladni`)},{t:'Sdílet kontakt',ic:'share',fn:()=>shareModal(c)},...(canManage(c)?[{t:'Předat kontakt',ic:'user-tick',fn:()=>handoverModal(c)},'-',{t:'Deaktivovat kontakt',ic:'trash',dng:1,fn:()=>deactModal([c])}]:[])]);};
// Kontakt, který má uživatel jen nasdílený, nesmí předat ani deaktivovat. Smí majitel, správce kontaktu, nadřízený a administrátor.
const canManage=c=>c.owner===ME||(c.managers||[]).includes(ME)||isMgr()||isAdmin();
const onlyManaged=(list,what)=>{const ok=list.filter(canManage),n=list.length-ok.length;if(n)toast(ok.length?(n===1?`1 vybraný kontakt máte jen nasdílený, ten ${what} nejde. Pokračuje se se zbylými ${ok.length}.`:`${n} z vybraných kontaktů máte jen nasdílené, ty ${what} nejde. Pokračuje se se zbylými ${ok.length}.`):`Vybrané kontakty máte jen nasdílené, ${what} je může jen jejich správce, nadřízený nebo administrátor.`);return ok;};
ACT.bulkhand=el=>{const l=onlyManaged(listState(el.dataset.t).sel.map(contact),'předat');if(l.length)handoverModal(null,l);};
ACT.bulkdeact=el=>{const l=onlyManaged(listState(el.dataset.t).sel.map(contact),'deaktivovat');if(l.length)deactModal(l,el.dataset.t);};
function deactModal(list,t){modal(`<h2>Deaktivovat ${list.length===1?esc(list[0].name):list.length+' '+czK(list.length)}?</h2><p class="mute">Nadřízený je může do 14 dnů obnovit.</p><div class="ft"><button class="btn" data-close>Zrušit</button><button class="btn danger" id="dc">Deaktivovat</button></div>`);
  document.getElementById('dc').onclick=()=>{list.forEach(c=>c.active=false);if(t)listState(t).sel=[];save();closeLayer();toast(list.length===1?'Kontakt deaktivován':`Deaktivováno ${list.length} kontaktů`,()=>{list.forEach(c=>c.active=true);save();});if(routeNow[0]==='kontakt')navRep('#/kontakty/'+(list[0].type==='osoba'?'osoby':'firmy'));else render();};}
const internal=()=>DB.users.filter(u=>u.state==='Aktivní');
function userOpts(sel,skip){return internal().filter(u=>u.id!==skip).map(u=>`<option value="${u.id}" ${u.id===sel?'selected':''}>${esc(u.name)}</option>`).join('');}
function shareModal(c){modal(`<h2>Sdílet kontakt: ${esc(c.name)}</h2><div class="stack" style="margin-top:16px"><div class="grid g2"><div class="field"><label>Pozvat kolegu</label><select class="inp" id="sw">${userOpts('LM',c.owner)}</select></div><div class="field"><label>Oprávnění</label><select class="inp" id="sp"><option>Může upravovat</option><option>Jen čtení</option></select></div></div><div class="field"><label>Platnost sdílení</label><select class="inp"><option>Bez omezení</option><option>30 dní</option></select></div><div class="over">Kdo má přístup</div><div class="row">${who(c.owner)}<span class="spacer"></span><span class="small mute">Hlavní správce · Vlastník</span></div></div><p class="small mute" style="margin-top:16px">Nevidí vaše osobní štítky a poznámky.</p><div class="ft"><button class="btn" data-close>Zrušit</button><button class="btn pri" id="sg">Sdílet</button></div>`,'w640');
  document.getElementById('sg').onclick=()=>{const u=user(document.getElementById('sw').value);c.sharedWith=[...new Set([...(c.sharedWith||[]),u.id])];addHistory(c,'Sdílení',`Sdílel kontakt: ${u.name}.`);save();closeLayer();toast('Kontakt sdílen: '+u.name);render();};}
function handoverModal(c,list){const items=list||[c];modal(`<h2>Předat ${items.length===1?'kontakt: '+esc(items[0].name):items.length+' '+czK(items.length)}</h2><div class="stack" style="margin-top:16px"><div class="field"><label>Nový hlavní správce</label><select class="inp" id="hw">${userOpts('AN',items[0].owner)}</select></div><div class="field"><label>Otevřené úkoly a obchody</label><select class="inp"><option>Předat s kontaktem</option><option>Nechat u současného správce</option></select></div><div class="field"><label>Poznámka pro nového správce</label><textarea class="inp" id="hn" placeholder="Např. Klientka preferuje telefon dopoledne."></textarea></div></div><div class="ft"><button class="btn" data-close>Zrušit</button><button class="btn pri" id="hg">Předat</button></div>`);
  document.getElementById('hg').onclick=()=>{const id=document.getElementById('hw').value;items.forEach(x=>{const old=x.owner;x.owner=id;addHistory(x,'Správce kontaktu',`Předal kontakt z ${user(old)?user(old).name:old} na ${user(id).name}.`);});Object.values(UI).forEach(v=>{if(v&&v.sel)v.sel=[];});save();closeLayer();toast(`Předáno: ${user(id).name}`);render();};}
function exportModal(n,total,pick){const big=n=>n>100;modal(`<h2>Exportovat kontakty</h2><div class="stack" style="margin-top:16px"><div class="field"><label>Rozsah</label><select class="inp" id="er"><option value="${total}">Všechny kontakty (864)</option><option value="${n}" ${pick?'selected':''}>${pick?'Vybrané kontakty':'Aktuální výběr'} (${n})</option></select></div><div class="field"><label>Formát</label><select class="inp"><option>Excel (XLSX)</option><option>CSV</option></select></div><label class="row"><input type="checkbox" class="cb">Zahrnout citlivé údaje (RČ, doklady, bankovní spojení)</label><div class="banner" id="ew">${ic('info-circle','s16')}<span>Export nad 100 kontaktů uvidí vedení.</span></div></div><div class="ft"><button class="btn" data-close>Zrušit</button><button class="btn pri" id="eg">Exportovat</button></div>`);
  const r=document.getElementById('er'),w=document.getElementById('ew');const up=()=>{w.style.display=big(+r.value)?'':'none';};r.onchange=up;up();
  document.getElementById('eg').onclick=()=>{const v=+r.value;closeLayer();if(big(v))DB.notifications.unshift({id:'n'+Date.now(),m:`${me().name} exportoval${me().g==='f'?'a':''} ${v} kontaktů`,d:'dnes '+NOW,k:'Export většího množství',un:true,to:'manager',go:'#/uzivatele'});save();toast(`Export ${v} kontaktů je připravený ke stažení`);render();};}
ACT.exportc=el=>{const t=el.dataset.t,s=listState(t);exportModal(el.dataset.sel?s.sel.length:filtered(t).length,864,!!el.dataset.sel);};

// ---- Detail ----
// Souhlasy a komunikace hned za Časovou osou: před oslovením se mají zkontrolovat, nesmí být schované za šipkou.
const TABS=[['zakladni','Základní údaje'],['osa','Časová osa'],['souhlasy','Souhlasy a komunikace'],['ukoly','Úkoly'],['obchod','Obchod'],['dokumenty','Dokumenty'],['dalsi','Další údaje'],['integrace','Integrace'],['historie','Historie změn']];
const F=(l,v)=>`<div class="field"><span class="lab">${l}</span><div class="val">${v==null||v===''?'—':v}</div></div>`;
const ensure=c=>{if(c.history)return c;c.history=[{who:'S',f:'Vytvoření kontaktu',t:'Vytvořil kontakt importem z Excelu.',d:'1. 9. 2026'}];const AK={call:['Hovor','call','Hovor s klientem'],mail:['E-mail','sms','E-mail klientovi'],meet:['Schůzka','people','Schůzka s klientem']}[c.actType];c.timeline=c.timeline||[...(AK&&c.act?[{g:tlGroup(c.act),k:AK[0],ic:AK[1],d:fmt(c.act),t:AK[2],x:'',who:c.owner}]:[]),{g:'Starší',k:'Systém',ic:'setting-2',d:'1. 9. 2026',t:'Kontakt vytvořen',x:'Kontakt byl přidán do systému importem z Excelu.',who:'S'}];c.consentTo=c.consentTo||'2028-09-01';c.consents=c.consents||{commercial:'Povoleno',marketing:'Neudělen',profiling:'Neudělen',personal:'Udělen'};c.addresses=c.addresses||[{id:'a1',type:c.type==='osoba'?'Trvalé bydliště':'Sídlo',def:true,street:'—',city:c.city,zip:'—',region:'—',state:'Česká republika'}];c.docs=c.docs||{op:false,driver:false,passport:false,other:false};c.links=c.links||[];c.personal=c.personal||[];return c;};
const tagCell=c=>{const all=[...c.tags,...(c.personal||[])];return `<button class="tag-btn" data-a="people" data-id="${c.id}" aria-haspopup="dialog">${all.length?`<span class="chip">${esc(all[0])}</span>${all.length>1?`<span class="av-more">+${all.length-1}</span>`:''}`:'<span class="mute">Žádné</span>'}</button>`;};
// --- Pomocné: odkazy, prázdná pole, oprávnění, plán a souhlasy ---
const mailA=(e,cl='')=>e?`<a class="${cl}" href="mailto:${esc(e)}">${esc(e)}</a>`:'';
const telA=(v,n)=>v?`<a data-a="call" data-v="${esc(v)}" data-n="${esc(n)}">${esc(v)}</a>`:'';
const webA=v=>v?`<a href="${/^https?:/.test(v)?esc(v):'https://'+esc(v)}" target="_blank" rel="noopener">${esc(v)}</a>`:'';
const blank=v=>v==null||v===''||v==='—';
const Fx=(l,v,raw)=>blank(raw===undefined?v:raw)?'':F(l,v);
const tipL=(l,t)=>`${l}<span class="info-tip" data-tip="${esc(t)}" aria-label="${esc(t)}">${ic('info-circle','s16')}</span>`;
const canSens=c=>c.owner===ME||(c.managers||[]).includes(ME)||isMgr()||isAdmin();
const MON=['ledna','února','března','dubna','května','června','července','srpna','září','října','listopadu','prosince'];
const tlGroup=iso=>{const days=Math.round((new Date(TODAY)-new Date(iso))/864e5);if(days>7)return 'Starší';const [y,m,dd]=iso.split('-');return `${+dd}. ${MON[+m-1]} ${y}`;};
const relDay=iso=>{const n=Math.round((new Date(iso)-new Date(TODAY))/864e5);return n===0?'dnes':n===1?'zítra':n<5?`za ${n} dny`:`za ${n} dní`;};
const KIND_IC={Hovor:'call','E-mail':'sms','Schůzka':'people','Poznámka':'note-text','Úkol':'task-square',Dokument:'document-text','Událost':'calendar'};
// Naplánované: události v kalendáři a otevřené úkoly s termínem od dneška
function cPlanned(c){const ev=DB.events.filter(e=>e.contact===c.id&&e.status==='Naplánovaná'&&(e.date>TODAY||(e.date===TODAY&&mins(e.end)>mins(NOW)))).map(e=>({k:['Hovor','Schůzka'].includes(e.type)?e.type:'Událost',t:e.title,iso:e.date,time:e.start,who:e.who[0],ev:e.id}));
  const ts=DB.tasks.filter(t=>taskContact(t)===c&&!t.done&&t.due&&t.due>=TODAY).map(t=>({k:KIND[t.cat]?t.cat:'Úkol',t:t.title,iso:t.due,time:t.time||'',who:t.who,task:t.id}));
  return [...ev,...ts].sort((a,b)=>(a.iso+(a.time||'99:99').padStart(5,'0')).localeCompare(b.iso+(b.time||'99:99').padStart(5,'0')));}
const cLast=c=>(c.timeline||[]).filter(t=>t.k!=='Systém').sort((a,b)=>dParse(b.d)-dParse(a.d))[0];
const consentState=c=>{const to=c.consentTo;if(!to)return null;const n=Math.round((new Date(to)-new Date(TODAY))/864e5);return n<0?['Souhlas vypršel '+fmt(to),'red','b-red']:n<=30?[`Souhlas končí ${fmt(to)}`,'amb','b-amb']:null;};
function contactNote(c){const cs=consentState(c);if(cs)return `<div class="small ${cs[1]}">${cs[0]}</div>`;if(c.consents&&!/Udělen$/.test(c.consents.marketing))return '<div class="small mute">Bez marketingového souhlasu</div>';return '';}
// Shrnutí: kontakt a aktivity v jednom řádku. Propojené kontakty, správci a štítky vždy rozbalené, při posouvání stránky se skryjí.
const sumIc=(i,cl,t)=>`<span class="cs-hint ${cl}" data-tip="${esc(t)}" aria-label="${esc(t)}">${ic(i,'s16')}</span>`;
function cSummary(c,next,last,when){const cs=consentState(c),l=c.links||[],own=[c.owner,...(c.managers||[]).filter(x=>x!==c.owner)];
  const chips=a=>a.length?`<div class="cs-tags">${a.map(t=>`<span class="chip">${esc(t)}</span>`).join('')}</div>`:'<span class="mute">Žádné</span>';
  const col=(lab,body,act)=>`<div class="cs-col"><div class="lab">${lab}</div>${body}${act?`<div class="cs-act-l">${act}</div>`:''}</div>`;
  const more=`<div class="cs-more">${col('Propojené kontakty',l.length?`<div class="links">${l.slice(0,3).map(linkRow).join('')}</div>`:'<span class="mute">Žádné</span>',(l.length>3?`<a data-a="links" data-id="${c.id}">Zobrazit další (${l.length-3})</a>`:'')+`<a data-a="linkadd" data-id="${c.id}">+ Přidat</a>`)}
    ${col('Správci kontaktu',`<div class="links">${own.slice(0,2).map(ownerRow).join('')}</div>`,(own.length>2?`<a data-a="owners" data-id="${c.id}">Zobrazit další (${own.length-2})</a>`:'')+(isMgr()||c.owner===ME?`<a data-a="ownersedit" data-id="${c.id}">Upravit správce</a>`:''))}
    ${col('Týmové štítky',chips(c.tags))}${col('Moje štítky',chips(c.personal||[]))}</div>`;
  return `<div class="summary c-sum"><div class="cs-row"><div class="cs-g">${F('E-mail',mailA(c.email)+(cs?`<div class="cs-sup ${cs[1]}">${cs[0]}</div>`:''))}${F('Telefon',telA(c.phone,c.name)+(when?`<div class="cs-sup">${when}</div>`:''))}</div>
    <div class="cs-g cs-a"><span class="cs-cal">${ic('calendar')}</span>${F('Následující aktivita',next)}${F('Poslední aktivita',last)}</div></div>
    ${more}</div>`;}
const linkCell=c=>{const l=c.links||[];if(!l.length)return `<button class="tag-btn" data-a="links" data-id="${c.id}" aria-haspopup="dialog"><span class="mute">Žádné</span></button>`;return `<button class="tag-btn link-btn" data-a="links" data-id="${c.id}" aria-haspopup="dialog"><span class="lk-one"><span>${esc(l[0].name)}</span><span class="small mute">${esc(l[0].role)}</span></span>${l.length>1?`<span class="av-more">+${l.length-1}</span>`:''}</button>`;};
ACT.links=el=>{const c=contact(el.dataset.id);popover(el,`<div style="padding:8px"><div class="over">Propojené kontakty</div><div class="links">${(c.links||[]).map(linkRow).join('')||'<span class="mute small">Žádné</span>'}</div><div class="own-ft"><a data-a="linkadd" data-id="${c.id}">+ Přidat propojený kontakt</a></div></div>`,360);};
function viewContact(id,tab){const c=contact(id);if(!c)return viewMissing('x');ensure(c);if(tab==='zakladni')remember('Kontakt',c.name,`#/kontakt/${c.id}/zakladni`);
  const isP=c.type==='osoba';const list=isP?'osoby':'firmy';
  const open=DB.tasks.filter(t=>taskContact(t)===c&&!t.done).length;
  const nx=cPlanned(c)[0],ls=cLast(c),m=c.meta||{};
  const next=nx?`<a href="#/kontakt/${c.id}/osa" class="plain">${fmt(nx.iso)}${nx.time?', '+nx.time:''}<div class="cs-sup">${esc(nx.k)} ${relDay(nx.iso)}</div></a>`:'<span class="mute">Nic naplánováno</span>';
  const last=ls?`<a href="#/kontakt/${c.id}/osa" class="plain">${esc(String(ls.d).split(',')[0])}<div class="cs-sup">${esc(ls.k)} • ${esc(ls.who==='S'?'Systém':shortName(ls.who))}</div></a>`:'<span class="mute">Zatím žádná</span>';
  const when=m.callHint?esc(m.callHint):[m.when,m.whenNo].filter(Boolean).map(x=>esc(String(x).replace(/\.$/,''))).join(' · ');
  const edit=['zakladni','dalsi','souhlasy'].includes(tab)?tab:'zakladni';
  const head=`<div class="crumbs"><a href="#/kontakty/${list}">Kontakty</a><span>/</span><a href="#/kontakty/${list}">${isP?'Osoby':'Organizace'}</a><span>/</span>${esc(c.name)}</div>
   ${(()=>{
    // Zavolat a napsat e-mail jde kliknutím přímo na telefon a e-mail ve shrnutí, v hlavičce nejsou.
    const pic=s=>c.photo?`<img class="av ${s} ${isP?'':'logo'}" src="${c.photo}" alt="">`:`<span class="av ${s}">${isP?esc((c.first||'')[0]+(c.last||'')[0]):ic('buildings',s==='a88'?'s32':'s16')}</span>`;
    const full=esc(c.titleBefore?c.titleBefore+' ':'')+esc(c.name)+(c.titleAfter?', '+esc(c.titleAfter):'');
    const acts=`<div class="ent-acts"><button class="btn pri" data-a="newtask" data-c="${c.id}">${ic('task','s16')}Přidat úkol</button><button class="btn pri" data-a="newact" data-c="${c.id}">${ic('calendar','s16')}Přidat aktivitu</button><a class="btn" data-rep href="#/kontakt/${c.id}/upravit/${edit}" aria-label="Editovat">${ic('edit-2','s16')}Editovat</a><button class="more" data-a="cmenu" data-id="${c.id}" aria-label="Další akce">${ic('more')}</button></div>`;
    // Hlavička a shrnutí odjedou s obsahem. Přilepí se jen pruh se záložkami; jakmile se přilepí, objeví se nad ním úzký řádek
    // se jménem, nejčastějšími údaji (telefon, e-mail, následující aktivita) a odkazem na celé shrnutí, které se rozbalí přes obsah.
    const sum=cSummary(c,next,last,when);
    const nxS=nx?`<a href="#/kontakt/${c.id}/osa">${nx.iso.split("-").slice(1).reverse().map(Number).join(". ")}.${nx.time?', '+nx.time:''} · ${esc(nx.k)} ${relDay(nx.iso)}</a>`:'<span class="mute">Nic naplánováno</span>';
    const facts=`${c.phone?`<span class="mf" data-tip="Telefon">${ic('call','s16')}${telA(c.phone,c.name)}</span>`:''}${c.email?`<span class="mf" data-tip="E-mail">${ic('sms','s16')}${mailA(c.email)}</span>`:''}<span class="mf mf-next" data-tip="Následující aktivita">${ic('calendar','s16')}${nxS}</span><button class="mf-tog" data-a="detsum" aria-expanded="false" aria-controls="dsum">Celé shrnutí${ic('arrow-down','s16')}</button>`;
    return `<div class="ent-head det-head">${pic('a88')}<div class="ent-name"><h1>${full}</h1><div class="row ent-meta">${rateOn()?rating(c.rating):''}${statusDot(c.status)}<span class="sep-dot" data-tip="Vztah ke kontaktu">${esc(c.rel)}</span></div></div>${acts}</div>
   ${sum}
   <div class="det-bar" id="dt"><div class="det-mini" inert>${pic('a40')}<div class="det-mini-b"><div class="det-mini-n" title="${full}">${full}</div><div class="det-mini-f">${facts}</div></div>${acts}</div>
   <div class="det-sum" id="dsum" hidden>${sum}</div>
   <nav class="tabs">${TABS.map(([k,l])=>`<a class="tab ${tab===k?'on':''}" href="#/kontakt/${c.id}/${k}">${l}${k==='ukoly'&&open?` (${open})`:''}</a>`).join('')}</nav></div>`;})()}`;
  const body={zakladni:tabBasic,osa:tabTimeline,ukoly:tabTasks,obchod:tabDeals,dokumenty:tabDocs,dalsi:tabExtra,integrace:tabInteg,historie:tabHist,souhlasy:tabConsents}[tab](c);
  return {nav:list,html:head+body};
}
// Prázdná pole se neukazují. Kolik jich chybí, říká odkaz do editace.
function tabBasic(c){const isP=c.type==='osoba';const st=ui('addr-'+c.id,{i:0});const a=c.addresses[st.i]||c.addresses[0];const ok=canSens(c);
  const vals=isP?[c.titleBefore,c.titleAfter,c.birth,c.rc,c.gender,c.bank,c.mobile,c.web,c.linkedin,c.skype]:[c.dic,c.form,c.mobile,c.web,c.linkedin,c.skype];const miss=vals.filter(blank).length;
  const sec=(t,inner,extra='')=>inner?`<h3 class="sec-t">${t}</h3>${inner}${extra}`:'';
  const g=(cls,items)=>{const h=items.join('');return h?`<div class="grid ${cls}">${h}</div>`:'';};
  const id1=isP?g('g4',[Fx('Tituly před jménem',esc(c.titleBefore),c.titleBefore),F('Jméno',esc(c.first)),F('Příjmení',esc(c.last)),Fx('Tituly za jménem',esc(c.titleAfter),c.titleAfter),Fx('Datum narození',esc(c.birth),c.birth),Fx('Rodné číslo',c.rc?sensitive(c.rc.slice(0,7)+'●●●●',c.rc,ok):'',c.rc),Fx('Pohlaví',esc(c.gender),c.gender),Fx('Bankovní spojení',c.bank?sensitive('●●●●●●/0800',c.bank,ok):'',c.bank)])
    :g('g4',[F('Název',esc(c.name)),Fx('IČO',c.ico?sensitive('●●●●●'+c.ico.slice(-3),c.ico,ok):'',c.ico),Fx('DIČ',esc(c.dic),c.dic),Fx('Právní forma',esc(c.form),c.form)]);
  const kont=g('g3',[Fx('Mobil',telA(c.mobile,c.name),c.mobile),Fx('Web',webA(c.web),c.web),Fx('LinkedIn',webA(c.linkedin),c.linkedin),Fx('Skype',esc(c.skype),c.skype)]);
  const adr=g('g2',[Fx('Ulice a číslo',esc(a.street),a.street),Fx('Město',esc(a.city),a.city),Fx('PSČ',esc(a.zip),a.zip),Fx('Kraj',esc(a.region),a.region),Fx('Stát',esc(a.state),a.state)]);
  const DOCS=[['op','Občanský průkaz'],['driver','Řidičský průkaz'],['passport','Pas'],['other','Jiné']],up=DOCS.filter(([k])=>c.docs[k]),left=DOCS.filter(([k])=>!c.docs[k]);
  const docs=isP?`<hr class="sep"><div class="card-head"><h3 class="sec-t" style="margin:0">Doklady</h3><div class="r"><a class="small" href="#/kontakt/${c.id}/dokumenty">${!left.length?'Doklady v Dokumentech':up.length?'Nahrát další doklad':'Nahrát doklad'}</a></div></div>${up.length?`<div class="grid g4">${up.map(([k,l])=>F(l,`<a data-a="docshow" data-id="${c.id}">Zobrazit doklad</a>`)).join('')}${c.docs.op&&c.opNo?F('Číslo OP',sensitive('●●●●●'+c.opNo.slice(-4),c.opNo,ok))+F('Datum vydání OP',c.opFrom||'15. 3. 2020')+F('Platnost OP do',c.opTo||'15. 3. 2030')+F('Vydávající úřad',c.opBy||'Magistrát města Brna'):''}</div>`:'<p class="mute">Zatím žádný doklad.</p>'}`:'';
  return `<section class="card"><div class="card-head"><h2>${isP?'Jméno a tituly':'Organizační údaje'}</h2>${miss?`<div class="r"><a class="small" data-rep href="#/kontakt/${c.id}/upravit/zakladni">Doplnit údaje (${miss})</a></div>`:''}</div>${id1}<hr class="sep">${kont?sec('Další kontaktní údaje',kont)+'<hr class="sep">':''}<div class="card-head"><h3 class="sec-t" style="margin:0">Adresy</h3><div class="r"><button class="btn" data-a="addrmanage" data-id="${c.id}">Spravovat adresy</button></div></div>${c.addresses.length>1?`<div class="sub-tabs" role="tablist">${c.addresses.map((x,i)=>`<button class="sub-tab ${i===st.i?'on':''}" role="tab" aria-selected="${i===st.i}" data-a="addrtab" data-id="${c.id}" data-i="${i}">${esc(x.type)}${x.def?' · Výchozí':''}</button>`).join('')}</div>`:`<div class="small mute" style="margin-bottom:16px">${esc(a.type)}${a.def?' · Výchozí':''}</div>`}<div class="addr">${adr||'<p class="mute">Adresa není vyplněná.</p>'}${addrMap(a)}</div>${docs}</section>`;}
ACT.docpick=el=>{const c=contact(el.dataset.id);openMenu(el,[['op','Občanský průkaz'],['driver','Řidičský průkaz'],['passport','Pas'],['other','Jiné']].filter(([k])=>!c.docs[k]).map(([k,l])=>({t:l,ic:'export',fn:()=>ACT.docup({dataset:{id:c.id,k,l}})})));};
// Propojený kontakt je vždy odkaz na jeho detail
const linkRow=l=>{const x=l.id?contact(l.id):DB.contacts.find(y=>y.name===l.name);const pic=x&&x.photo?`<img class="av a32 ${x.type==='osoba'?'':'logo'}" src="${x.photo}" alt="">`:`<span class="av a32 ${l.org?'org':''}">${l.org?ic('buildings','s16'):esc(l.name.split(' ').map(w=>w[0]).join('').slice(0,2))}</span>`;const body=`${pic}<span class="link-b"><span class="med">${esc(l.name)}</span><span class="small mute">${esc(l.role)}${x&&!x.active?' · Neaktivní':''}</span></span>`;return x?`<a class="link-r" href="#/kontakt/${x.id}/zakladni">${body}${ic('arrow-right-2','s16')}</a>`:`<div class="link-r off">${body}</div>`;};
// Mapa adresy (Google Maps, vložená bez klíče API, jen pro prototyp)
const addrMap=a=>{const q=[a.street,[a.zip,a.city].filter(v=>v&&v!=='—').join(' '),a.state].filter(v=>v&&v!=='—').join(', ');if(!q)return '';const u=encodeURIComponent(q);return `<div class="map"><iframe title="Mapa: ${esc(q)}" src="https://maps.google.com/maps?q=${u}&z=15&output=embed" loading="lazy" referrerpolicy="no-referrer-when-downgrade"></iframe><a class="small" href="https://www.google.com/maps/search/?api=1&query=${u}" target="_blank" rel="noopener">Otevřít v Google Mapách</a></div>`;};
const docCell=(c,k,l)=>F(l,c.docs[k]?`<a data-a="docshow" data-id="${c.id}">Zobrazit doklad</a>`:`<span class="mute">Nenahráno</span> <a data-a="docup" data-id="${c.id}" data-k="${k}" data-l="${l}">Nahrát</a>`);
ACT.docshow=el=>{const d=DB.documents.find(x=>x.contact===el.dataset.id&&x.type==='Doklad'&&x.active!==false);if(d)go('#/dokumenty/detail/'+d.id);};
ACT.docup=el=>{const c=contact(el.dataset.id);c.docs[el.dataset.k]=true;DB.documents.push({id:'doc'+Date.now(),title:el.dataset.l,type:'Doklad',file:'JPG',state:'Nahráno',contact:c.id,deal:null,owner:ME,added:TODAY,version:1,links:[],log:[{who:ME,t:'Nahráno.',d:'14. 9. 2026, '+NOW}],sensitive:true,active:true});addHistory(c,'Dokument',`Nahrál doklad: ${el.dataset.l}.`);save();toast(el.dataset.l+' je nahraný');render();};
ACT.addrtab=el=>{ui('addr-'+el.dataset.id,{i:0}).i=+el.dataset.i;render();};
ACT.addrmanage=el=>{const c=contact(el.dataset.id);const types=c.type==='osoba'?['Trvalé bydliště','Korespondenční adresa','Pobočka']:['Sídlo','Korespondenční adresa','Pobočka'];const body=()=>c.addresses.map((a,i)=>`<div class="row" style="padding:8px 0;border-bottom:1px solid var(--n100)"><div class="spacer"><div class="med">${esc(a.type)}${a.def?' · Výchozí':''}</div><div class="small mute">${esc(a.street)}, ${esc(a.city)}</div></div>${a.def?'':`<button class="btn" data-a="addrdef" data-id="${c.id}" data-i="${i}">Nastavit jako výchozí</button><button class="more" data-a="addrdel" data-id="${c.id}" data-i="${i}" aria-label="Deaktivovat adresu">${ic('trash','s16')}</button>`}</div>`).join('');
  modal(`<h2>Spravovat adresy</h2><div id="al">${body()}</div><div class="grid g2" style="margin-top:16px"><div class="field"><label>Typ nové adresy</label><select class="inp" id="nt">${types.map(t=>`<option>${t}</option>`).join('')}</select></div><div class="field"><label>Ulice a číslo</label><input class="inp" id="ns" placeholder="Začněte psát adresu"></div><div class="field"><label>Město</label><input class="inp" id="nc"></div><div class="field"><label>PSČ</label><input class="inp" id="nz"></div></div><div class="ft"><button class="btn pri" id="ad">Hotovo</button></div>`,'w640');
  document.getElementById('ad').onclick=()=>{const s=document.getElementById('ns').value.trim(),ci=document.getElementById('nc').value.trim();if(s||ci){c.addresses.push({id:'a'+Date.now(),type:document.getElementById('nt').value,street:s||'—',city:ci||'—',zip:document.getElementById('nz').value||'—',region:'—',state:'Česká republika'});addHistory(c,'Adresa',`Přidal adresu ${s}.`);toast('Adresa je přidaná');}save();closeLayer();render();};};
ACT.addrdef=el=>{const c=contact(el.dataset.id);c.addresses.forEach((a,i)=>a.def=i===+el.dataset.i);save();closeLayer();ACT.addrmanage(el);render();ACT.addrmanage(el);};
ACT.addrdel=el=>{const c=contact(el.dataset.id);c.addresses.splice(+el.dataset.i,1);addHistory(c,'Adresa','Deaktivoval adresu.');save();render();ACT.addrmanage(el);toast('Adresa deaktivována');};
ACT.people=el=>{const c=contact(el.dataset.id);popover(el,`<div style="padding:8px"><div class="over">Týmové štítky</div><div class="row" style="flex-wrap:wrap;margin:4px 0 16px">${c.tags.map(t=>`<span class="chip">${esc(t)}</span>`).join('')||'<span class="mute small">Žádné</span>'}</div><div class="over">Osobní štítky</div><div class="row" style="flex-wrap:wrap;margin:4px 0 16px">${(c.personal||[]).map(t=>`<span class="chip">${esc(t)}</span>`).join('')||'<span class="mute small">Žádné</span>'}</div></div>`,320);};
const ownerRow=id=>{const u=user(id);return u?`<a class="own-r" href="#/uzivatel/${id}/prehled">${av(id)}<span class="own-b"><span class="med">${esc(u.name)}</span><span class="small mute">${esc(u.pos)}</span></span>${availBadge(u.avail)}</a>`:'';};
ACT.owners=el=>{const c=contact(el.dataset.id),mg=(c.managers||[]).filter(x=>x!==c.owner),sh=(c.sharedWith||[]).filter(x=>x!==c.owner&&!mg.includes(x));popover(el,`<div style="padding:8px"><div class="over">Hlavní správce</div>${ownerRow(c.owner)}${mg.length?`<div class="over" style="margin-top:8px">Další správci</div>${mg.map(ownerRow).join('')}`:''}${sh.length?`<div class="over" style="margin-top:8px">Sdíleno s</div>${sh.map(ownerRow).join('')}`:''}${isMgr()||c.owner===ME?`<div class="own-ft"><button class="btn" data-a="ownersedit" data-id="${c.id}">Upravit správce</button></div>`:''}</div>`,360);};
ACT.cmenu=el=>{const c=contact(el.dataset.id);openMenu(el,[{t:'Sdílet kontakt',ic:'share',fn:()=>shareModal(c)},...(canManage(c)?[{t:'Předat kontakt',ic:'user-tick',fn:()=>handoverModal(c)}]:[]),{t:'Exportovat kontakt',ic:'export',fn:()=>toast('Kontakt je exportovaný')},...(canManage(c)?['-',{t:'Deaktivovat kontakt',ic:'trash',dng:1,fn:()=>deactModal([c])}]:[])]);};

const TL_LIM=6;
function tabTimeline(c){const s=ui('tl-'+c.id,{k:'',old:false,plan:false});const kinds=[...new Set(c.timeline.map(t=>t.k))];const all=c.timeline.map((t,i)=>({t,i})).filter(x=>!s.k||x.t.k===s.k);const list=s.old?all:all.slice(0,TL_LIM);let g='';const plan=cPlanned(c).filter(p=>!s.k||p.k===s.k);
  const prow=p=>`<${p.task?`a href="#/ukol/${p.task}"`:`button data-a="calopen" data-id="${p.ev}"`} class="tl tl-l tl-fut"><span class="i ${kindCls(p.k)}">${ic(KIND_IC[p.k]||'calendar','s16')}</span><span class="spacer"><span class="row tl-h"><span class="badge ${kindCls(p.k)}">${esc(p.k)}</span><span class="small mute">${fmt(p.iso)}${p.time?', '+p.time:''} · ${relDay(p.iso)}</span><span class="spacer"></span>${who(p.who)}</span><span class="med tl-t">${esc(p.t)}</span></span></${p.task?'a':'button'}>`;
  return `<section class="card"><div class="card-head"><h2>Časová osa</h2><div class="r"><select class="inp" style="width:200px;height:32px" data-a="tlk" data-on="change" data-id="${c.id}" aria-label="Filtrovat"><option value="">Všechny aktivity</option>${kinds.map(k=>`<option ${s.k===k?'selected':''}>${k}</option>`).join('')}</select><button class="btn pri" data-a="newact" data-c="${c.id}">${ic('add','s16')}Přidat aktivitu</button></div></div>${plan.length?`<button class="tl-tog" data-a="tlplan" data-id="${c.id}" aria-expanded="${s.plan}">${ic(s.plan?'arrow-up-2':'arrow-down','s16')}Naplánované (${plan.length})</button>${s.plan?`<div class="tl-plan">${plan.map(prow).join('')}</div>`:''}`:''}${list.map(({t,i})=>{const h=t.g!==g?`<div class="over tl-g">${esc(t.g)}</div>`:'';g=t.g;const dl=t.deal&&DB.deals.find(x=>x.id===t.deal);return h+`<div class="tl tl-l" data-a="tlopen" data-id="${c.id}" data-i="${i}" role="button" tabindex="0" aria-label="Otevřít aktivitu: ${esc(t.t)}"><span class="i ${kindCls(t.k)}">${ic(t.ic,'s16')}</span><div class="spacer"><div class="row tl-h"><span class="badge ${kindCls(t.k)}">${esc(t.k)}</span>${t.b?`<span class="badge">${esc(t.b)}</span>`:''}${t.res?`<span class="badge">${esc(CALL_LAB[t.res]||t.res)}</span>`:''}<span class="small mute">${esc(t.d)}</span><span class="spacer"></span>${who(t.who)}</div><div class="med tl-t">${esc(t.t)}</div>${t.x?`<div class="mute tl-x">${esc(t.x)}</div>`:''}${dl?`<div class="small tl-x">Obchod: ${esc(dl.title)}</div>`:''}</div></div>`;}).join('')}${all.length>TL_LIM?`<button class="tl-tog tl-more" data-a="tlold" data-id="${c.id}">${s.old?'Zobrazit jen nejnovější':'Načíst starší ('+(all.length-TL_LIM)+')'}</button>`:''}</section>`;}
ACT.tlplan=el=>{const s=ui('tl-'+el.dataset.id,{});s.plan=!s.plan;render();};
ACT.tlold=el=>{const s=ui('tl-'+el.dataset.id,{});s.old=!s.old;render();};
const CALL_LAB={'Dovoláno':'Dovoláno','Schůzka':'Domluvena schůzka','Později':'Zavolat později','Nedostupný':'Nedostupný','Odmítnuto':'Odmítnuto'};
// Detail aktivity: zápis je rychlý, podrobnosti se doplní tady
ACT.tlopen=el=>{const c=contact(el.dataset.id),t=c.timeline[+el.dataset.i];if(!t)return;const deals=DB.deals.filter(x=>x.contact===c.id),sys=t.k==='Systém';
  modal(`<div class="row" style="gap:8px"><span class="badge ${kindCls(t.k)}">${esc(t.k)}</span><span class="small mute">${esc(t.d)} · ${esc(t.who==='S'?'Systém':(user(t.who)||{}).name||'')}</span></div>${sys?`<h2 style="margin-top:8px">${esc(t.t)}</h2><p class="mute" style="margin-top:8px">${esc(t.x)}</p>`:`<div class="stack" style="margin-top:16px"><div class="field"><label for="ae-t">Předmět</label><input class="inp" id="ae-t" value="${esc(t.t)}"></div><div class="field"><label for="ae-x">Podrobnosti</label><textarea class="inp" id="ae-x">${esc(t.x||'')}</textarea></div><div class="grid g2"><div class="field"><label for="ae-d">Kdy</label><input class="inp" id="ae-d" value="${esc(t.d)}"></div>${t.k==='Hovor'?`<div class="field"><label for="ae-r">Výsledek hovoru</label><select class="inp" id="ae-r"><option value="">Neuvedeno</option>${Object.keys(CALL_LAB).map(k=>`<option value="${k}" ${t.res===k?'selected':''}>${CALL_LAB[k]}</option>`).join('')}</select></div>`:''}</div>${deals.length?`<div class="field"><label for="ae-o">Obchod</label><select class="inp" id="ae-o"><option value="">Bez obchodu</option>${deals.map(x=>`<option value="${x.id}" ${t.deal===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div>`:''}</div><div class="ft"><button class="btn" data-close>Zrušit</button><button class="btn pri" id="ae-s">Uložit</button></div>`}`,'w640');
  if(sys)return;document.getElementById('ae-s').onclick=()=>{const v=id=>{const e=document.getElementById(id);return e?e.value:undefined;};const ti=v('ae-t').trim();if(!ti){document.getElementById('ae-t').classList.add('err');return;}t.t=ti;t.x=v('ae-x');t.d=v('ae-d')||t.d;if(v('ae-r')!==undefined){t.res=v('ae-r');if(t===c.timeline.find(x=>x.k==='Hovor')&&CALL_RES.includes(t.res))c.callRes=t.res;}if(v('ae-o')!==undefined)t.deal=v('ae-o')||null;save();closeLayer();toast('Aktivita je uložená');render();};};
ACT.tlk=el=>{ui('tl-'+el.dataset.id,{}).k=el.value;render();};
// Přidat aktivitu (11/2026): zaznamenat, co proběhlo, nebo naplánovat hovor či schůzku s datem a časem.
// Naplánovaná aktivita se uloží jako událost v Kalendáři, takže se ukáže i jako Následující aktivita a v Naplánovaných.
const ACT_IC={Hovor:'call','E-mail':'sms','Schůzka':'people','Poznámka':'note-text'},ACT_T={Hovor:'call','E-mail':'mail','Schůzka':'meet','Poznámka':'note'};
const nextSlot=()=>{const m=mins(NOW);const h=Math.floor(m/60)+1;return [`${h}:00`,`${h}:30`];};
const addMin=(t,n)=>{const m=mins(t)+n;return `${Math.floor(m/60)}:${pad2(m%60)}`;};
ACT.newact=el=>{const c=contact(el.dataset.c);ensure(c);const st={plan:el.dataset.plan==='1'};
  const draw=()=>{const p=st.plan,types=p?['Hovor','Schůzka']:['Hovor','E-mail','Schůzka','Poznámka'];const [s0,e0]=nextSlot();
    modal(`<h2>Přidat aktivitu: ${esc(c.name)}</h2>
    <div class="seg seg-l act-mode" role="tablist" style="margin-top:16px"><button class="${p?'':'on'}" id="am0" role="tab" aria-selected="${!p}">Zaznamenat proběhlou</button><button class="${p?'on':''}" id="am1" role="tab" aria-selected="${p}">Naplánovat</button></div>
    
    <div class="stack" style="margin-top:16px"><div class="grid g2"><div class="field"><label for="at">Typ</label><select class="inp" id="at">${types.map(t=>`<option>${t}</option>`).join('')}</select></div><div class="field"><label for="as">Předmět *</label><input class="inp" id="as"><div class="err-t" id="ase"></div></div></div>
    <div class="grid ${p?'g3':'g2'}"><div class="field"><label for="ad">Datum</label><input type="date" class="inp" id="ad" value="${TODAY}" ${p?`min="${TODAY}"`:`max="${TODAY}"`}></div><div class="field"><label for="a1">${p?'Od':'Čas'}</label><input type="time" class="inp" id="a1" value="${p?pad2(mins(s0)/60|0)+':00':pad2(mins(NOW)/60|0)+':'+pad2(mins(NOW)%60)}"></div>${p?`<div class="field"><label for="a2">Do</label><input type="time" class="inp" id="a2" value="${pad2(mins(e0)/60|0)}:30"></div>`:''}</div>
    ${p?`<div class="field" id="apw"><label for="ap">Místo</label><input class="inp" id="ap" placeholder="Telefon, adresa nebo odkaz na online schůzku"></div>`:''}
    <div class="field"><label for="ax">Podrobnosti</label><textarea class="inp" id="ax"></textarea></div></div>
    <div class="ft"><button class="btn" data-close>Zrušit</button><button class="btn pri" id="ag">${p?'Naplánovat':'Zapsat do časové osy'}</button></div>`);
    document.getElementById('am0').onclick=()=>{st.plan=false;draw();};document.getElementById('am1').onclick=()=>{st.plan=true;draw();};
    document.getElementById('as').focus();
    document.getElementById('ag').onclick=()=>{const v=id=>(document.getElementById(id)||{}).value||'';const k=v('at'),s=document.getElementById('as');
      if(!s.value.trim()){s.classList.add('err');document.getElementById('ase').textContent='Vyplňte předmět.';s.focus();return;}
      const d=v('ad')||TODAY,t1=v('a1').replace(/^0(\d)/,'$1');
      if(st.plan){let t2=v('a2').replace(/^0(\d)/,'$1');if(!t2||mins(t2)<=mins(t1))t2=addMin(t1,30);
        DB.events.push({id:'e'+Date.now(),title:`${k}: ${s.value.trim()}`,type:k,date:d,start:t1,end:t2,who:[ME],contact:c.id,place:v('ap')||(k==='Hovor'?'Telefon':''),status:'Naplánovaná',note:v('ax')});
        addHistory(c,'Aktivita',`Naplánoval: ${k.toLowerCase()} ${fmt(d)}, ${t1}.`);save();closeLayer();toast(`${k} je ${k==="Schůzka"?"naplánovaná":"naplánovaný"} na ${fmt(d)}, ${t1}`);render();return;}
      const [y,m,dd]=d.split('-');c.timeline.unshift({g:`${+dd}. ${MON[+m-1]} ${y}`,k,ic:ACT_IC[k],b:k==='Poznámka'?undefined:'Proběhlo',d:`${fmt(d)}${t1?', '+t1:''}`,t:s.value.trim(),x:v('ax'),who:ME});
      if(d>=(c.act||'')){c.act=d;c.actType=ACT_T[k];}if(k==='Hovor')c.called=d;save();closeLayer();toast('Aktivita je zapsaná v časové ose');navRep(`#/kontakt/${c.id}/osa`);};};
  draw();};
function tabTasks(c){const ts=DB.tasks.filter(t=>taskContact(t)===c);return taskBoard(ts,'ct-'+c.id,{hideWho:false});}
ACT.stub=el=>toast(el.dataset.m2);
function tabExtra(c){const e=c.extra||{},m=c.meta||{};const g1=`${c.type==='osoba'?Fx('Rodinný stav',e.rodinny)+Fx('Počet dětí',e.deti)+Fx('Pracovní status',e.status):Fx('Počet zaměstnanců',e.empl)+Fx('Obrat',e.turn)}${Fx('Obor / odvětví',e.obor)}${Fx('Smluvní souvislost',e.smluvni)}${Fx('Poznámka',e.pozn)}`;
  /* Prázdná pole se skrývají; když není vyplněné nic, karta to řekne a nabídne doplnění */
  return `<section class="card"><h3 class="sec-t">${c.type==='osoba'?'Osobní údaje':'Organizační údaje'}</h3>${g1?`<div class="grid g3">${g1}</div>`:`<p class="small mute">Zatím nevyplněno. <a data-rep href="#/kontakt/${c.id}/upravit/dalsi">Doplnit údaje</a></p>`}</section><section class="card"><h3 class="sec-t">Obchodní klasifikace</h3><div class="grid g3">${Fx(tipL('Priorita kontaktu','Jak naléhavě se kontaktu věnovat právě teď. Mění se podle situace.'),m.priority)}${Fx(tipL('Obchodní potenciál','Odhad, kolik obchodů může kontakt přinést v budoucnu.'),m.potential)}${Fx(tipL('Rizikovost','Riziko, že kontakt nezaplatí včas nebo odejde ke konkurenci.'),m.risk)}${F('Odpovědný tým',m.team||'Sales')}${Fx('Interní poznámka',m.internal)}</div></section><section class="card"><h3 class="sec-t">Marketingové údaje</h3><div class="grid g3">${F('Zdroj kontaktu',esc(m.source||'Import z Excelu'))}${Fx('Kampaň',esc(m.campaign||''),m.campaign)}${Fx('Segment',esc(m.segment||''),m.segment)}</div></section><section class="card"><h3 class="sec-t">Vlastní pole</h3><div class="grid g3">${DB.settings.fields.filter(x=>x.on).map(x=>F(esc(x.n),esc((c.custom||{})[x.id]||''))).join('')}</div></section><section class="card"><h3 class="sec-t">Externí identifikátory</h3><div class="grid g3">${F('Interní ID',m.intId||c.id.toUpperCase())}${Fx('Externí CRM ID',m.extId)}${Fx('ID z účetního systému',m.accId)}</div></section>`;}
function tabInteg(c){const I=c.integrations,m=c.meta||{};return `<section class="card"><h3 class="sec-t">Propojené systémy</h3>${I?I.map(x=>`<div class="tl integ-r">${integIc(x[1])}<div class="spacer"><div class="sb">${x[1]}</div><div class="small mute">${esc(x[2])}</div></div><div style="text-align:right">${x[3].startsWith('Chyba')?`<span class="badge b-red">${x[3]}</span>`:`<span class="badge b-grn">${x[3]}</span>`}<div class="small mute" style="margin-top:4px">${x[4]}</div></div>${x[3].startsWith('Chyba')?`<button class="btn" data-a="reauth" data-id="${c.id}">Znovu autorizovat</button>`:''}</div>`).join(''):'<p class="mute">Kontakt není propojený s žádným systémem.</p>'}</section>`;}
ACT.reauth=el=>{const c=contact(el.dataset.id);const x=c.integrations.find(i=>i[3].startsWith('Chyba'));x[3]='Synchronizováno';x[4]='14. 9. 2026, '+NOW;x[2]='anna@javor.example';save();toast('Microsoft Outlook je znovu propojený');render();};
function tabHist(c){const s=ui('h-'+c.id,{f:''});const kinds=[...new Set(c.history.map(h=>h.f))];return `<section class="card"><div class="card-head"><h2>Historie změn</h2><div class="r"><select class="inp" style="width:200px;height:32px" data-a="hfilter" data-on="change" data-id="${c.id}" aria-label="Filtrovat"><option value="">Všechny změny</option>${kinds.map(k=>`<option ${s.f===k?'selected':''}>${esc(k)}</option>`).join('')}</select></div></div>${(()=>{const hl=c.history.filter(h=>!s.f||h.f===s.f),lim=s.n||20;return hl.slice(0,lim).map(h=>`<div class="tl">${av(h.who,'a32')}<div class="spacer"><div class="row"><span class="sb">${esc(user(h.who)?user(h.who).name:'Systém')}</span><span class="badge">${esc(h.f)}</span></div><div>${esc(femV(h.who,h.t))}</div></div><span class="small mute nowrap">${esc(h.d)}</span></div>`).join('')+(hl.length>lim?`<button class="tl-tog tl-more" data-a="hmore" data-id="${c.id}">Načíst starší (${hl.length-lim})</button>`:'');})()}</section>`;}
ACT.hmore=el=>{const s=ui('h-'+el.dataset.id,{});s.n=(s.n||20)+20;render();};
ACT.hfilter=el=>{ui('h-'+el.dataset.id,{}).f=el.value;render();};
// Organizace: GDPR souhlasy a oslovení patří lidem, ne firmě. U firmy jen kdy volat, komu a obchodní sdělení; souhlasy lidí jako přehled s odkazem.
function orgConsents(c){const s=c.consents||{},m=c.meta||{};const ok=v=>/Udělen$|Povoleno/.test(v||'')&&v!=='Neudělen';
  const people=(c.links||[]).map(l=>l.id&&contact(l.id)).filter(x=>x&&x.type==='osoba');
  const role=x=>((c.links||[]).find(l=>l.id===x.id)||{}).role||'';
  const pState=x=>{const cs=consentState(x),k=x.consents||{};if(cs)return `<span class="badge ${cs[2]}">${esc(cs[0])}</span>`;return ok(k.marketing)?'<span class="badge b-grn">Marketing udělen</span>':'<span class="badge">Bez marketingového souhlasu</span>';};
  const when=contactHow(c);
  const ppl=`<section class="card"><div class="card-head"><h3 class="sec-t" style="margin:0">Lidé a jejich souhlasy</h3></div><p class="small mute" style="margin-bottom:8px">Souhlasy se evidují u konkrétních lidí.</p>${people.length?people.map(x=>`<a class="link-r cons-r" href="#/kontakt/${x.id}/souhlasy">${x.photo?`<img class="av a32" src="${x.photo}" alt="">`:`<span class="av a32">${esc((x.first||'')[0]+(x.last||'')[0])}</span>`}<span class="link-b"><span class="med">${esc(x.name)}</span><span class="small mute">${esc(role(x))}</span></span>${pState(x)}${ic('arrow-right-2','s16')}</a>`).join(''):`<p class="mute">K organizaci zatím není připojený žádný člověk. <a data-a="linkadd" data-id="${c.id}">+ Připojit kontaktní osobu</a></p>`}</section>`;
  const row=(l,v,k)=>`<div class="row" style="padding:8px 0;border-bottom:1px solid var(--n100);justify-content:space-between;min-height:48px"><span>${l}</span><span class="row"><span class="badge ${consCls(v)}">${esc(v||'Neuvedeno')}</span></span></div>`;
  const firm=`<section class="card"><h3 class="sec-t">Komunikace s organizací</h3>${row('Obchodní sdělení na firemní adresy',s.commercial,'commercial')}</section>`;
  return when+ppl+firm;}
// Jak a kdy kontaktovat: jedna karta. Kanál a jazyk jako údaje, kdy volat a oslovení jen jednou.
const LANGS=/^(Čeština|Slovenština|Angličtina|Němčina|Polština|Ukrajinština)$/;
function contactHow(c){const m=c.meta||{},pr=m.prefs||[];if(!m.how&&!m.when&&!pr.length)return '';const isP=c.type==='osoba';
  const ch=m.prefChannel||pr.find(x=>/^(Telefon|E-mail|SMS)$/.test(x))||'',lg=pr.filter(x=>LANGS.test(x)).join(', ');
  const box=(t,v,sub,bg)=>v?`<div class="how-b" style="background:var(--${bg})"><div class="over sb">${t}</div><div class="med">${esc(v)}</div>${sub?`<div class="small mute">${esc(sub)}</div>`:''}</div>`:'';
  return `<section class="card"><h3 class="sec-t">Jak a kdy kontaktovat</h3><div class="grid ${isP&&m.how&&m.when?'g2':''}">${isP?box('Jak komunikovat',m.how,m.greeting?'Oslovení: '+m.greeting:'','teal-bg'):''}${box('Kdy kontaktovat',m.when,m.whenNo,'blue-bg')}</div><div class="grid g3" style="margin-top:16px">${Fx('Preferovaný kanál',esc(ch),ch)}${Fx('Jazyk',esc(lg),lg)}${F('Newsletter',c.newsletter?'Aktivní':'Vypnutý')}</div></section>`;}
// Barva souhlasu (rozhodnutí 13. 11. 2026): udělený zeleně, odvolaný červeně, neudělený šedě (běžný stav, ne riziko).
const consCls=v=>/^(Udělen|Povoleno)$/.test(v||'')?'b-grn':/^Odvolán/.test(v||'')?'b-red':'';
// Souhlasy se v náhledu jen zobrazují, mění se v editaci (rozhodnutí 13. 11. 2026, bez výjimky z pravidla Náhled ≠ editace).
function tabConsents(c){if(c.type!=='osoba')return orgConsents(c);const s=c.consents,m=c.meta||{};
  const b=v=>`<span class="badge ${consCls(v)}">${esc(v)}</span>`;
  return `${contactHow(c)}<section class="card"><h3 class="sec-t">Souhlasy a komunikace</h3>${[['Souhlas se zpracováním osobních údajů',b(s.personal)+' <a data-a="cdetail" data-id="'+c.id+'" data-k="personal">Detail</a>'],['Datum udělení souhlasu',m.consentDate||'1. 9. 2026'],['Marketingový souhlas',b(s.marketing)+' <a data-a="cdetail" data-id="'+c.id+'" data-k="marketing">Detail</a>'],['Obchodní sdělení',b(s.commercial)],['Souhlas s profilováním',b(s.profiling)],['Zdroj souhlasu',m.consentSource||m.source||'Import z Excelu'],['Platnost souhlasu do',(()=>{const cs=consentState(c);return (m.consentUntil||fmt(c.consentTo))+(cs?` <span class="badge ${cs[2]}">${cs[1]==='red'?'Vypršel':'Končí '+relDay(c.consentTo)}</span>`:'');})()]].map(r=>`<div class="row" style="padding:8px 0;border-bottom:1px solid var(--n100);justify-content:space-between;min-height:48px"><span>${r[0]}</span><span class="row">${r[1]}</span></div>`).join('')}</section>`;}
// Souhlasy v editaci: klíč formuláře → [klíč v c.consents, popisek, možnosti]
const CONS_F={cs_personal:['personal','Souhlas se zpracováním osobních údajů',['Udělen','Odvolán']],cs_marketing:['marketing','Marketingový souhlas',['Udělen','Neudělen','Odvolán']],cs_commercial:['commercial','Obchodní sdělení',['Povoleno','Neudělen','Odvoláno']],cs_profiling:['profiling','Souhlas s profilováním',['Udělen','Neudělen','Odvolán']]};
const CONS_F_ORG={cs_commercial:['commercial','Obchodní sdělení na firemní adresy',['Povoleno','Neuvedeno','Odvoláno']]};
const CONS_SRC=['Telefonicky','Webový formulář','Písemně','Import z Excelu'];

// ---- Editace: stejné názvy záložek jako v náhledu ----
// Integrace nemají editovatelná pole (marketingové údaje jsou v Dalších údajích), proto v editaci nejsou.
const ETABS=[['zakladni','Základní údaje'],['souhlasy','Souhlasy a komunikace'],['dalsi','Další údaje']];
const I=(k,l,v,o={})=>`<div class="field"><label for="f-${k}">${l}${o.req?' *':''}</label>${o.opts?`<select class="inp" id="f-${k}" name="${k}">${o.opts.map(x=>`<option ${x===v?'selected':''}>${x}</option>`).join('')}</select>`:`<input class="inp" id="f-${k}" name="${k}" value="${esc(v||'')}" ${o.dis?'disabled':''} ${o.ph?`placeholder="${o.ph}"`:''}>`}${o.hint?`<div class="small mute" style="margin-top:4px">${o.hint}</div>`:''}<div class="err-t" data-err="${k}"></div></div>`;
const photoBlock=c=>{const isP=c.type==='osoba',w=isP?'fotografii':'logo';return `<div class="ph-edit"><span id="ph-prev" data-org="${isP?'':1}" data-ini="${esc((c.first||'')[0]||'')}${esc((c.last||'')[0]||'')}"></span><input type="hidden" name="photo" id="f-photo" value="${esc(c.photo||'')}"><label class="btn">${ic('export','s16')}Nahrát ${w}<input type="file" accept="image/*" hidden data-a="photopick" data-on="change"></label><button type="button" class="btn" id="ph-del" data-a="photodel">Odebrat</button></div>`;};
window.photoSync=()=>{const p=document.getElementById('ph-prev'),i=document.getElementById('f-photo');if(!p||!i)return;const org=p.dataset.org==='1';p.innerHTML=i.value?`<img class="av a88 ${org?'logo':''}" src="${i.value}" alt="">`:`<span class="av a88">${org?ic('buildings','s32'):esc(p.dataset.ini)||ic('user','s32')}</span>`;document.getElementById('ph-del').style.display=i.value?'':'none';};
ACT.photopick=el=>{const file=el.files&&el.files[0];el.value='';if(!file)return;if(!/^image\//.test(file.type)){toast('Vyberte obrázek');return;}const org=document.getElementById('ph-prev').dataset.org==='1',url=URL.createObjectURL(file),im=new Image();im.onerror=()=>{URL.revokeObjectURL(url);toast('Obrázek se nepodařilo načíst');};im.onload=()=>{const max=240,r=Math.min(1,max/Math.max(im.width,im.height)),cv=document.createElement('canvas');cv.width=Math.round(im.width*r);cv.height=Math.round(im.height*r);cv.getContext('2d').drawImage(im,0,0,cv.width,cv.height);URL.revokeObjectURL(url);document.getElementById('f-photo').value=cv.toDataURL(org?'image/png':'image/jpeg',.85);window.photoSync();};im.src=url;};
ACT.photodel=()=>{document.getElementById('f-photo').value='';window.photoSync();};
function viewContactForm(id,tab){
  const isNew=id.startsWith('novy-');let c=isNew?{id:'',type:id.slice(5),first:'',last:'',name:'',status:'Potenciální',rel:'Odběratel',rating:3,phone:'',email:'',tags:[],addresses:[],consents:{commercial:'Povoleno',marketing:'Neudělen',profiling:'Neudělen',personal:'Udělen'}}:ensure(contact(id));
  const isP=c.type==='osoba',scope=`#/kontakt/${id}/upravit/`,mt=c.meta||{};if(!dirty||dirty.scope!==scope)dirty={scope};dirty.at=location.hash;dirty.backTo=isNew?null:`#/kontakt/${id}/${tab}`;
  const tabsHtml=isNew?'':`<nav class="tabs">${ETABS.map(([k,l])=>`<a class="tab ${tab===k?'on':''}" href="#/kontakt/${id}/upravit/${k}">${l}</a>`).join('')}</nav>`;
  let body='';
  if(tab==='zakladni'||isNew)body=`<section class="card">${photoBlock(c)}<h3 class="sec-t">${isP?'Jméno a tituly':'Organizační údaje'}</h3><div class="grid g4" style="margin-bottom:16px">${isP?I('titleBefore','Tituly před jménem',c.titleBefore)+I('first','Jméno',c.first,{req:1})+I('last','Příjmení',c.last,{req:1})+I('titleAfter','Tituly za jménem',c.titleAfter):I('name','Název',c.name,{req:1})+I('ico','IČO',c.ico||'',{hint:'8 číslic'})+I('dic','DIČ',c.dic||'')+I('form','Právní forma',c.form||'s.r.o.',{opts:['s.r.o.','a.s.','z.s.','OSVČ']})}</div>${isP?`<div class="grid g4">${I('birth','Datum narození',c.birth)}${I('rc','Rodné číslo',c.rc,{hint:'9 nebo 10 číslic'})}${I('gender','Pohlaví',c.gender,{opts:['Žena','Muž','Neuvedeno']})}${I('bank','Bankovní spojení',c.bank,{})}</div>`:''}<hr class="sep"><h3 class="sec-t">Kontaktní údaje</h3><div class="grid g3">${I('email','E-mail',c.email)}${I('phone','Telefon',c.phone,{req:1})}${I('mobile','Mobil',c.mobile)}${I('web','Web',c.web)}${I('linkedin','LinkedIn',c.linkedin)}${I('skype','Skype',c.skype)}</div><hr class="sep"><h3 class="sec-t">Zařazení</h3><div class="grid g3">${I('status','Stav',c.status,{opts:DB.settings.statuses})}${I('rel','Vztah',c.rel,{opts:['Odběratel','Partner','Dodavatel','Konkurent']})}${rateOn()?I('rating','Hodnocení',String(c.rating),{opts:['1','2','3','4','5']}):''}</div><hr class="sep"><h3 class="sec-t">Štítky</h3><div class="grid g2">${tagField('tags','Týmové štítky',c.tags||[],false)}${tagField('ptags','Moje štítky',c.personal||[],true)}</div></section>`;
  else if(tab==='dalsi'){const e=c.extra||{};body=`<section class="card"><h3 class="sec-t">${isP?'Osobní údaje':'Organizační údaje'}</h3><div class="grid g3">${isP?I('x_rodinny','Rodinný stav',e.rodinny)+I('x_deti','Počet dětí',e.deti)+I('x_status','Pracovní status',e.status):I('x_empl','Počet zaměstnanců',e.empl)+I('x_turn','Obrat',e.turn)}${I('x_obor','Obor / odvětví',e.obor)}${I('x_smluvni','Smluvní souvislost',e.smluvni)}${I('x_pozn','Poznámka',e.pozn)}</div></section><section class="card"><h3 class="sec-t">Marketingové údaje</h3><div class="grid g3">${I('src','Zdroj kontaktu',mt.source||'Import z Excelu')}${I('camp','Kampaň',mt.campaign)}${I('seg','Segment',mt.segment)}</div></section><section class="card"><h3 class="sec-t">Vlastní pole</h3><div class="grid g3">${DB.settings.fields.filter(x=>x.on).map(x=>I('cf_'+x.id,x.n,(c.custom||{})[x.id]||'')).join('')}</div></section>`;}
  else body=`<section class="card"><h3 class="sec-t">Preference komunikace</h3><div class="grid g3">${I('p1','Preferovaný kanál',mt.prefChannel||'Telefon',{opts:['Telefon','E-mail','SMS']})}${I('p2','Doba kontaktu',mt.prefTime||'Dopoledne',{opts:['Dopoledne','Odpoledne','Kdykoli']})}${I('p3','Doporučené oslovení',mt.greeting)}</div></section>${(()=>{const cs=c.consents||{},src=mt.consentSource||mt.source||'Import z Excelu',srcO=CONS_SRC.includes(src)?CONS_SRC:[src,...CONS_SRC];
    const sel=Object.entries(isP?CONS_F:CONS_F_ORG).map(([k,[ck,l,o]])=>{const v=cs[ck]||o[1];return I(k,l,v,{opts:o.includes(v)?o:[v,...o]});}).join('');
    return isP?`<section class="card"><h3 class="sec-t">Souhlasy</h3><p class="small mute" style="margin-bottom:16px">Každá změna souhlasu se zapíše do Historie změn. Newsletter se řídí marketingovým souhlasem.</p><div class="grid g2">${sel}${I('cs_src','Zdroj souhlasu',src,{opts:srcO})}${I('cs_until','Platnost souhlasu do',mt.consentUntil||fmt(c.consentTo))}</div></section>`
      :`<section class="card"><h3 class="sec-t">Komunikace s organizací</h3><p class="small mute" style="margin-bottom:16px">Souhlasy se zpracováním údajů a marketingem se upravují u jednotlivých lidí. Změna se zapíše do Historie změn.</p><div class="grid g2">${sel}</div></section>`;})()}`;
  const back=isNew?`#/kontakty/${isP?'osoby':'firmy'}`:`#/kontakt/${id}/${tab}`;
  return {nav:isP?'osoby':'firmy',html:`<div class="crumbs"><a href="#/kontakty/${isP?'osoby':'firmy'}">Kontakty</a><span>/</span>${isNew?'Nový kontakt':esc(c.name)+'<span>/</span>Upravit kontakt'}</div><div class="page-head"><h1>${isNew?(isP?'Přidat osobu':'Přidat organizaci'):'Upravit: '+esc(c.name)}</h1></div>${tabsHtml}<form data-form id="cf" onsubmit="return false">${body}</form><div class="form-foot"><button class="btn" data-a="formcancel" data-back="${back}">Zrušit</button><button class="btn pri" data-a="contactsave" data-id="${id}" data-tab="${tab}">Uložit kontakt</button></div>`};
}
ACT.formcancel=el=>{if(history.state&&history.state.i>0){history.back();return;}navRep(el.dataset.back);};
function formData(id){const o={};document.querySelectorAll(`#${id} [name]`).forEach(i=>o[i.name]=i.value.trim());return o;}
function showErrs(errs){document.querySelectorAll('[data-err]').forEach(e=>e.textContent='');document.querySelectorAll('.inp.err').forEach(e=>e.classList.remove('err'));let first=null;Object.entries(errs).forEach(([k,m])=>{const e=document.querySelector(`[data-err="${k}"]`),i=document.getElementById('f-'+k);if(e)e.textContent=m;if(i){i.classList.add('err');first=first||i;}});if(first)first.focus();return !first;}
const META={src:'source',camp:'campaign',seg:'segment',p1:'prefChannel',p2:'prefTime',p3:'greeting'};
ACT.contactsave=el=>{const id=el.dataset.id,tab=el.dataset.tab,isNew=id.startsWith('novy-');dirtyCollect();const d=Object.assign({},dirty?dirty.draft:{},formData('cf')),errs={};Object.keys(d).forEach(k=>{d[k]=String(d[k]).trim();});
  if('first' in d&&!d.first)errs.first='Jméno je povinné.';if('last' in d&&!d.last)errs.last='Příjmení je povinné.';if('name' in d&&!d.name)errs.name='Název je povinný.';
  if('email' in d&&d.email&&!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(d.email))errs.email='Zkontrolujte e-mail, chybí v něm zavináč nebo doména.';
  if('rc' in d&&d.rc&&!/^\d{9,10}$/.test(d.rc.replace('/','')))errs.rc='Rodné číslo má 9 nebo 10 číslic.';
  if('phone' in d&&!d.phone)errs.phone='Telefon je povinný.';if('ico' in d&&d.ico&&!/^\d{8}$/.test(d.ico))errs.ico='IČO má 8 číslic.';
  if(Object.keys(errs).length&&tab!=='zakladni'&&!isNew){navRep(`#/kontakt/${id}/upravit/zakladni`);setTimeout(()=>showErrs(errs),60);return;}
  if(!showErrs(errs))return;
  let c;if(isNew){const ty=id.slice(5);c={id:'c'+Date.now(),type:ty,tags:[],owner:ME,act:TODAY,actType:'call',active:true,shared:false,city:'Brno',personal:[]};DB.contacts.push(c);ensure(c);c.history=[{who:ME,f:'Vytvoření kontaktu',t:'Vytvořil kontakt ručně.',d:'14. 9. 2026, '+NOW}];}else c=contact(id);
  const before=JSON.stringify(c);const sens={rc:'Rodné číslo',bank:'Bankovní spojení',ico:'IČO'},lab={email:'E-mail',phone:'Telefon',status:'Stav',rel:'Vztah',rating:'Hodnocení'};
  Object.entries(d).forEach(([k,v])=>{if(k.startsWith('cs_')){c.consents=c.consents||{};c.meta=c.meta||{};
      if(k==='cs_src'||k==='cs_until'){const mk=k==='cs_src'?'consentSource':'consentUntil',old=k==='cs_src'?(c.meta.consentSource||c.meta.source||'Import z Excelu'):(c.meta.consentUntil||fmt(c.consentTo));if(old!==v){c.meta[mk]=v;if(!isNew)addHistory(c,'Souhlas',`${k==='cs_src'?'Zdroj souhlasu':'Platnost souhlasu do'}: ${old||'—'} → ${v||'—'}.`);}return;}
      const [ck,l]=(c.type==='osoba'?CONS_F:CONS_F_ORG)[k]||CONS_F[k];if((c.consents[ck]||'')!==v){if(!isNew)addHistory(c,'Souhlas',`${l}: ${c.consents[ck]||'—'} → ${v}.`);c.consents[ck]=v;if(ck==='marketing')c.newsletter=v==='Udělen';}return;}
    if(k==='tags'||k==='ptags'){const nv=v?v.split('|').filter(Boolean):[],key=k==='tags'?'tags':'personal',old=c[key]||[];if(old.join('|')!==nv.join('|')){if(!isNew){nv.filter(x=>!old.includes(x)).forEach(x=>addHistory(c,'Štítek',`Přidal štítek „${x}“.`));old.filter(x=>!nv.includes(x)).forEach(x=>addHistory(c,'Štítek',`Odebral štítek „${x}“.`));}c[key]=nv;}return;}if(k.startsWith('cf_')){c.custom=c.custom||{};c.custom[k.slice(3)]=v;return;}if(k.startsWith('x_')){c.extra=c.extra||{};c.extra[k.slice(2)]=v;return;}if(META[k]){c.meta=c.meta||{};c.meta[META[k]]=v;return;}if(k==='photo'){if((c.photo||'')!==v){if(!isNew)addHistory(c,c.type==='osoba'?'Fotografie':'Logo',v?`Změnil ${c.type==='osoba'?'fotografii':'logo'}.`:`Odebral ${c.type==='osoba'?'fotografii':'logo'}.`);c.photo=v;}return;}const nv=k==='rating'?+v:v;if(c[k]!==nv&&(c[k]||v)){if(!isNew&&lab[k])addHistory(c,lab[k],`Změnil ${lab[k].toLowerCase()} z „${c[k]||'—'}“ na „${nv}“.`);if(!isNew&&sens[k]){addHistory(c,sens[k],`Změnil ${sens[k].toLowerCase()}. Odesláno upozornění.`);DB.notifications.unshift({id:'n'+Date.now(),m:`${me().name} změnil${me().g==='f'?'a':''} citlivý údaj u kontaktu ${c.name}`,d:'dnes '+NOW,k:'Citlivý údaj',un:true,to:'manager',go:`#/kontakt/${c.id}/historie`});}c[k]=nv;}});
  if(c.type==='osoba'&&(d.first||d.last))c.name=(c.first+' '+c.last).trim();
  save();dirty=null;toast(JSON.stringify(c)===before?'Nebylo co ukládat':'Změny jsou uložené');navRep(`#/kontakt/${c.id}/${isNew?'zakladni':tab}`);};
// Celé shrnutí z přilepeného řádku: rozbalí se přes obsah (stránka neposkočí), zavře se kliknutím mimo, Esc nebo návratem nahoru.
function detSum(open){const p=document.getElementById('dsum'),b=document.querySelector('.det-mini [data-a="detsum"]');if(!p)return;p.hidden=!open;if(b){b.setAttribute('aria-expanded',open);b.classList.toggle('on',open);}}
ACT.detsum=()=>{const p=document.getElementById('dsum');if(p)detSum(p.hidden);};
document.addEventListener('click',e=>{const p=document.getElementById('dsum');if(p&&!p.hidden&&!e.target.closest('#dsum,[data-a="detsum"],#layer'))detSum(false);},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape')detSum(false);});

// ---- 5. kolo: hromadné akce, štítky v editaci, okno propojení, správci, ikony integrací ----
ICONS['tag-r']=ICONS['tag-r']||['0 0 24 24','<path d="M4.16 15.3l4.53 4.53a4.78 4.78 0 006.75 0l4.39-4.39a4.78 4.78 0 000-6.75L15.3 4.16a4.75 4.75 0 00-3.6-1.39l-5 .24a3.86 3.86 0 00-3.69 3.67l-.24 5c-.06 1.35.45 2.66 1.39 3.62z" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/><path d="M9 9.5h6" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/>'];

// Hromadné akce: jedno okno s nabídkou, akce pak vede do svého kroku
const BULK=[['hand','user-tick','Předat','Nový hlavní správce',1],['share','share','Sdílet','Zpřístupnit kolegovi'],['tagadd','tag','Přidat štítek','Týmový štítek všem vybraným'],['tagdel','tag-r','Odebrat štítek','Týmový štítek u vybraných'],['status','status-up','Změnit stav','Stejný stav všem vybraným'],['task','task','Naplánovat úkol','Úkol ke každému kontaktu'],['export','export','Exportovat','Excel nebo CSV'],['deact','trash','Deaktivovat','Obnovit jde do 14 dnů',1]];
const bulkSel=t=>listState(t).sel.map(contact).filter(Boolean);
const bulkDone=(t,msg,undo)=>{listState(t).sel=[];save();closeLayer();toast(msg,undo);render();};
const bulkFt=(t,id,lab,dng)=>`<div class="ft"><button class="btn" data-a="bulkmenu" data-t="${t}">${ic('arrow-left-2','s16')}Zpět</button><span class="spacer"></span><button class="btn ${dng?'danger':'pri'}" id="${id}">${lab}</button></div>`;
const czK=n=>n===1?'kontakt':n>1&&n<5?'kontakty':'kontaktů';
ACT.bulkmenu=el=>{const t=el.dataset.t,l=bulkSel(t),man=l.filter(canManage).length;
  modal(`<h2>Hromadné akce</h2><p class="small mute">Vybráno: ${l.length} ${czK(l.length)}</p><div class="bk-list">${BULK.map(([k,i,n,d,m])=>{const off=m&&!man;return `<button class="bk-it ${k==='deact'?'dng':''}" data-a="bulkdo" data-t="${t}" data-k="${k}" ${off?'disabled':''}><span class="bk-ic">${ic(i,'s16')}</span><span class="bk-b"><span class="med">${n}</span><span class="small mute">${off?'Jen pro správce kontaktů':m&&man<l.length?`${d} · lze u ${man} z ${l.length}`:d}</span></span>${ic('arrow-right-2','s16')}</button>`;}).join('')}</div>`);};
ACT.bulkdo=el=>{const t=el.dataset.t,k=el.dataset.k,l=bulkSel(t);
  if(k==='hand'){const ok=onlyManaged(l,'předat');if(ok.length)handoverModal(null,ok);return;}
  if(k==='deact'){const ok=onlyManaged(l,'deaktivovat');if(ok.length)deactModal(ok,t);return;}
  if(k==='export'){exportModal(l.length,864,true);return;}
  if(k==='share'){modal(`<h2>Sdílet ${l.length} ${czK(l.length)}</h2><div class="grid g2" style="margin-top:16px"><div class="field"><label for="bs-u">Kolega</label><select class="inp" id="bs-u">${userOpts('',ME)}</select></div><div class="field"><label for="bs-p">Oprávnění</label><select class="inp" id="bs-p"><option>Může upravovat</option><option>Jen čtení</option></select></div></div>${bulkFt(t,'bs-g','Sdílet')}`);
    document.getElementById('bs-g').onclick=()=>{const u=user(document.getElementById('bs-u').value);l.forEach(c=>{ensure(c);c.sharedWith=[...new Set([...(c.sharedWith||[]),u.id])];addHistory(c,'Sdílení',`Sdílel kontakt: ${u.name}.`);});bulkDone(t,`Sdíleno s: ${u.name}`);};return;}
  if(k==='tagadd'||k==='tagdel'){const add=k==='tagadd',tags=add?DB.settings.tags:[...new Set(l.flatMap(c=>c.tags))];
    if(!tags.length){toast('Vybrané kontakty nemají žádný týmový štítek');return;}
    const cnt=g=>l.filter(c=>c.tags.includes(g)).length;
    modal(`<h2>${add?'Přidat':'Odebrat'} štítek</h2><p class="small mute">${l.length} ${czK(l.length)}</p><div class="pick-list" style="margin-top:16px">${tags.map((g,i)=>`<label class="pick-r"><input type="radio" name="bt" value="${esc(g)}" ${i?'':'checked'}><span class="spacer">${esc(g)}</span>${l.length>1?`<span class="small mute">${cnt(g)} z ${l.length}</span>`:''}</label>`).join('')}</div>${bulkFt(t,'bt-g',add?'Přidat štítek':'Odebrat štítek',!add)}`);
    document.getElementById('bt-g').onclick=()=>{const g=document.querySelector('[name=bt]:checked').value,prev=l.map(c=>[c,c.tags.slice()]);l.forEach(c=>{ensure(c);const has=c.tags.includes(g);if(add&&!has){c.tags=[...c.tags,g];addHistory(c,'Štítek',`Přidal štítek „${g}“.`);}if(!add&&has){c.tags=c.tags.filter(x=>x!==g);addHistory(c,'Štítek',`Odebral štítek „${g}“.`);}});bulkDone(t,`Štítek „${g}“ ${add?'přidán':'odebrán'}`,()=>{prev.forEach(([c,tg])=>c.tags=tg);save();});};return;}
  if(k==='status'){modal(`<h2>Změnit stav</h2><p class="small mute">${l.length} ${czK(l.length)}</p><div class="pick-list" style="margin-top:16px">${DB.settings.statuses.map((g,i)=>`<label class="pick-r"><input type="radio" name="bst" value="${esc(g)}" ${i?'':'checked'}><span class="spacer">${statusDot(g)}</span>${l.length>1?`<span class="small mute">${l.filter(c=>c.status===g).length} z ${l.length}</span>`:''}</label>`).join('')}</div>${bulkFt(t,'bst-g','Změnit stav')}`);
    document.getElementById('bst-g').onclick=()=>{const g=document.querySelector('[name=bst]:checked').value,prev=l.map(c=>[c,c.status]);l.forEach(c=>{if(c.status!==g){ensure(c);addHistory(c,'Stav',`Změnil stav z „${c.status}“ na „${g}“.`);c.status=g;}});bulkDone(t,'Stav: '+g,()=>{prev.forEach(([c,v])=>c.status=v);save();});};return;}
  if(k==='task'){modal(`<h2>Naplánovat úkol</h2><p class="small mute">Vytvoří se ${l.length} ${l.length===1?'úkol':l.length<5?'úkoly':'úkolů'}, ke každému kontaktu jeden.</p><div class="stack" style="margin-top:16px"><div class="field"><label for="bk-n">Název *</label><input class="inp" id="bk-n" placeholder="Např. Zavolat kvůli prodloužení"><div class="err-t" id="bk-e"></div></div><div class="grid g2"><div class="field"><label for="bk-d">Termín</label><input class="inp" type="date" id="bk-d" value="${TODAY}"></div><div class="field"><label for="bk-c">Kategorie</label><select class="inp" id="bk-c">${['Hovor','E-mail','Dokument','Kontrola','Administrativa'].map(x=>`<option>${x}</option>`).join('')}</select></div></div><div class="field"><label for="bk-w">Řešitel</label><select class="inp" id="bk-w">${userOpts(ME)}</select></div></div>${bulkFt(t,'bk-g','Naplánovat')}`);
    document.getElementById('bk-g').onclick=()=>{const n=document.getElementById('bk-n');if(!n.value.trim()){n.classList.add('err');document.getElementById('bk-e').textContent='Vyplňte název úkolu.';n.focus();return;}const v=id=>document.getElementById(id).value;l.forEach((c,i)=>DB.tasks.push({id:'t'+Date.now()+i,title:n.value.trim(),cat:v('bk-c'),due:v('bk-d'),time:'',who:v('bk-w'),contact:c.id,project:null,done:false,desc:'',prio:'Střední',by:ME,created:'14. 9. 2026'}));bulkDone(t,`Naplánováno ${l.length} ${l.length===1?'úkol':l.length<5?'úkoly':'úkolů'}`);};return;}
};

