// Štítky v editaci: týmové = výběr z nabídky (bez vytváření), osobní = našeptávání s možností vytvořit nový
function tagField(name,label,vals,create){const ph=dirty&&dirty.draft&&dirty.draft[name]!==undefined?dirty.draft[name]:vals.join('|');
  return `<div class="field"><label for="tb-${name}">${label}</label><div class="tagbox" data-tb="${name}" data-create="${create?1:''}"><input type="hidden" name="${name}" id="f-${name}" value="${esc(ph)}"><span class="tb-chips"></span><input class="tb-in" id="tb-${name}" autocomplete="off" placeholder="${create?'Napište štítek':'Vyberte štítek'}" role="combobox" aria-expanded="false" aria-autocomplete="list"><div class="tb-dd" hidden role="listbox"></div></div></div>`;}
const tbVals=box=>{const h=box.querySelector('input[type=hidden]');return h.value?h.value.split('|').filter(Boolean):[];};
const tbSet=(box,v)=>{box.querySelector('input[type=hidden]').value=v.join('|');tbDraw(box);};
function tbDraw(box){box.querySelector('.tb-chips').innerHTML=tbVals(box).map(v=>`<span class="chip">${esc(v)}<button type="button" data-tbdel="${esc(v)}" aria-label="Odebrat ${esc(v)}">×</button></span>`).join('');}
const tbPool=box=>box.dataset.create?[...new Set(DB.contacts.flatMap(c=>c.personal||[]))].sort(csSort):DB.settings.tags;
function tbOpen(box){const i=box.querySelector('.tb-in'),dd=box.querySelector('.tb-dd'),q=normStr(i.value.trim()),cur=tbVals(box);
  const opts=tbPool(box).filter(v=>!cur.includes(v)&&(!q||normStr(v).includes(q))).slice(0,8);
  const make=box.dataset.create&&i.value.trim()&&!tbPool(box).concat(cur).some(v=>normStr(v)===q);
  dd.innerHTML=opts.map((v,n)=>`<button type="button" class="it ${n?'':'act'}" data-tbadd="${esc(v)}">${esc(v)}</button>`).join('')+(make?`<button type="button" class="it ${opts.length?'':'act'}" data-tbadd="${esc(i.value.trim())}">${ic('add','s16')}Vytvořit „${esc(i.value.trim())}“</button>`:'')+(!opts.length&&!make?`<div class="small mute" style="padding:8px">${box.dataset.create?'Napište název nového štítku':'Žádný další štítek'}</div>`:'');
  const rb=box.getBoundingClientRect();dd.classList.toggle('up',rb.bottom+296>innerHeight-72&&rb.top>320);
  dd.hidden=false;i.setAttribute('aria-expanded','true');}
const tbClose=()=>document.querySelectorAll('.tb-dd').forEach(d=>{d.hidden=true;const i=d.parentElement.querySelector('.tb-in');if(i)i.setAttribute('aria-expanded','false');});
const _ps=window.photoSync;window.photoSync=()=>{if(_ps)_ps();document.querySelectorAll('.tagbox').forEach(tbDraw);};
document.addEventListener('focusin',e=>{const i=e.target.closest&&e.target.closest('.tb-in');if(i)tbOpen(i.closest('.tagbox'));});
document.addEventListener('input',e=>{const i=e.target.closest&&e.target.closest('.tb-in');if(i)tbOpen(i.closest('.tagbox'));});
document.addEventListener('mousedown',e=>{const a=e.target.closest('[data-tbadd]'),d=e.target.closest('[data-tbdel]');const box=(a||d)&&(a||d).closest('.tagbox');
  if(a){e.preventDefault();tbSet(box,[...tbVals(box),a.dataset.tbadd]);const i=box.querySelector('.tb-in');i.value='';tbOpen(box);return;}
  if(d){e.preventDefault();tbSet(box,tbVals(box).filter(v=>v!==d.dataset.tbdel));return;}
  if(!e.target.closest('.tagbox'))tbClose();});
document.addEventListener('keydown',e=>{const i=e.target.closest&&e.target.closest('.tb-in');if(!i)return;const box=i.closest('.tagbox');
  if(e.key==='Enter'){e.preventDefault();const f=box.querySelector('.tb-dd [data-tbadd]');if(f){tbSet(box,[...tbVals(box),f.dataset.tbadd]);i.value='';tbOpen(box);}}
  else if(e.key==='Backspace'&&!i.value){const v=tbVals(box);if(v.length)tbSet(box,v.slice(0,-1));}
  else if(e.key==='Escape'){e.stopPropagation();tbClose();}});
document.addEventListener('click',e=>{const b=e.target.closest('.tagbox');if(b&&!e.target.closest('button'))b.querySelector('.tb-in').focus();});

// Přidat propojený kontakt: modální okno s hledáním, výběrem a vztahem
ACT.linkadd=el=>{const c=contact(el.dataset.id);ensure(c);let pick=null;const isO=c.type==='organizace';
  const roles=[...new Set([...(isO?['Jednatel','Jednatelka','Kontaktní osoba','Zaměstnanec','Zaměstnankyně']:[]),...Object.values(REL_ROLES).flat(),'Jednatel','Jednatelka','Kontaktní osoba','Dodavatel','Odběratel'])];
  modal(`<h2>Přidat propojený kontakt</h2><div class="stack" style="margin-top:16px"><div class="field"><label for="lk">Kontakt</label><input class="inp" id="lk" placeholder="Hledat osobu nebo organizaci" autocomplete="off"></div><div class="pick-list lk-res" id="lkr" role="listbox" aria-label="Výsledky"></div><div class="field"><label for="lr">Vztah *</label><input class="inp" id="lr" list="lr-opts" placeholder="Např. Jednatelka"><datalist id="lr-opts">${roles.map(r=>`<option value="${r}">`).join('')}</datalist><div class="err-t" id="lre"></div></div></div><div class="ft"><button class="btn" data-close>Zrušit</button><button class="btn pri" id="lkg" disabled>Propojit</button></div>`,'w640');
  const i=document.getElementById('lk'),res=document.getElementById('lkr'),g=document.getElementById('lkg');
  const done=new Set((c.links||[]).map(l=>l.id));
  const up=()=>{const q=normStr(i.value);const all=DB.contacts.filter(x=>x.id!==c.id&&x.active&&!done.has(x.id)&&(!q||normStr(x.name+' '+(x.email||'')+' '+(x.city||'')).includes(q)));const l=all.slice(0,30);
    res.innerHTML=l.length?l.map(x=>`<button type="button" class="pick-r ${pick===x.id?'on':''}" role="option" aria-selected="${pick===x.id}" data-lk="${x.id}">${x.photo?`<img class="av a32 ${x.type==='osoba'?'':'logo'}" src="${x.photo}" alt="">`:`<span class="av a32">${x.type==='osoba'?esc((x.first||'')[0]+(x.last||'')[0]):ic('buildings','s16')}</span>`}<span class="spacer link-b"><span class="med">${esc(x.name)}</span><span class="small mute">${x.type==='osoba'?'Osoba':'Organizace'}${x.city?' · '+esc(x.city):''}</span></span>${pick===x.id?ic('tick-circle','s16 grn'):''}</button>`).join('')+(all.length>l.length?`<div class="small mute" style="padding:8px">Dalších ${all.length-l.length}, upřesněte hledání.</div>`:''):'<div class="small mute" style="padding:16px 8px">Nic jsme nenašli.</div>';};
  res.onclick=e=>{const b=e.target.closest('[data-lk]');if(!b)return;pick=b.dataset.lk;g.disabled=false;up();};
  i.oninput=up;up();i.focus();
  g.onclick=()=>{const t=contact(pick),r=document.getElementById('lr').value.trim();if(!r){document.getElementById('lr').classList.add('err');document.getElementById('lre').textContent='Vyplňte vztah.';return;}
    c.links.push({id:t.id,name:t.name,role:r,org:t.type==='organizace'?1:0});addHistory(c,'Propojení',`Propojil kontakt s ${t.name} v roli ${r}.`);const br=linkBack(c,t,r);if(br){ensure(t);addHistory(t,'Propojení',`Propojil kontakt s ${c.name} v roli ${br}.`);}save();closeLayer();toast(`Propojeno: ${t.name}`);render();};};

// Správci kontaktu: hledání, vybraní nahoře, seznam po skupinách, hlavní správce pevně
ACT.ownersedit=el=>{const c=contact(el.dataset.id);let sel=(c.managers||[]).filter(x=>x!==c.owner);const mine=me(),boss=mine.boss;
  const us=DB.users.filter(u=>u.state==='Aktivní'&&u.id!==c.owner).sort((a,b)=>csSort(a.name,b.name));
  const inTeam=u=>u.boss===ME||u.id===boss||(boss&&u.boss===boss);
  modal(`<h2>Správci kontaktu</h2><p class="small mute">${esc(c.name)}</p><div class="own-main">${av(c.owner)}<span class="own-b"><span class="med">${esc(user(c.owner).name)}</span><span class="small mute">${esc(user(c.owner).pos)}</span></span><span class="badge">Hlavní správce</span></div>${canManage(c)?`<div class="small mute" style="margin-top:8px">Hlavního správce změníte <a data-a="ownhand" data-id="${c.id}">předáním kontaktu</a>.</div>`:''}<div class="field" style="margin-top:24px"><label for="oq">Další správci</label><div class="own-chips" id="och"></div><input class="inp" id="oq" placeholder="Hledat kolegu" autocomplete="off"></div><div class="own-pick" id="ol"></div><div class="ft"><button class="btn" data-close>Zrušit</button><button class="btn pri" id="os">Uložit</button></div>`,'w640');
  const q=document.getElementById('oq'),lst=document.getElementById('ol'),ch=document.getElementById('och');
  const row=u=>`<label class="pick-r"><input type="checkbox" class="cb" data-own="${u.id}" ${sel.includes(u.id)?'checked':''}>${av(u.id)}<span class="spacer link-b"><span class="med">${esc(u.name)}</span><span class="small mute">${esc(u.pos)}${u.branch?' · '+esc(u.branch):''}</span></span></label>`;
  const draw=()=>{const n=normStr(q.value),f=us.filter(u=>!n||normStr(u.name+' '+u.pos+' '+(u.branch||'')).includes(n)),a=f.filter(inTeam),b=f.filter(u=>!inTeam(u));
    lst.innerHTML=(a.length?`<div class="over own-g">Můj tým</div>${a.map(row).join('')}`:'')+(b.length?`<div class="over own-g">Ostatní</div>${b.map(row).join('')}`:'')||'<div class="small mute" style="padding:16px 8px">Nikoho jsme nenašli.</div>';
    ch.innerHTML=sel.map(id=>`<span class="chip">${av(id,'a20')}${esc(user(id).name)}<button type="button" data-ownx="${id}" aria-label="Odebrat ${esc(user(id).name)}">×</button></span>`).join('');ch.hidden=!sel.length;};
  lst.onchange=e=>{const x=e.target.dataset.own;if(!x)return;sel=e.target.checked?[...sel,x]:sel.filter(y=>y!==x);draw();};
  ch.onclick=e=>{const b=e.target.closest('[data-ownx]');if(!b)return;sel=sel.filter(y=>y!==b.dataset.ownx);draw();};
  q.oninput=draw;draw();q.focus();
  document.getElementById('os').onclick=()=>{const was=(c.managers||[]).join();c.managers=sel;if(was!==sel.join()){addHistory(c,'Správce kontaktu',`Upravil další správce: ${sel.map(x=>user(x).name).join(', ')||'žádní'}.`);toast('Správci jsou uložení');}save();closeLayer();render();};};
ACT.ownhand=el=>{const c=contact(el.dataset.id);handoverModal(c);};

// Detail souhlasu
ACT.cdetail=el=>{const c=contact(el.dataset.id),k=el.dataset.k,m=c.meta||{},v=c.consents[k],ok=/Udělen$|Povoleno/.test(v)&&v!=='Neudělen';const doc=DB.documents.find(d=>d.contact===c.id&&d.type==='Souhlas'&&d.active!==false);
  modal(`<h2>${k==='personal'?'Souhlas se zpracováním osobních údajů':'Marketingový souhlas'}</h2><div class="grid g2" style="margin-top:16px">${F('Stav',`<span class="badge ${consCls(v)}">${esc(v)}</span>`)}${F('Uděleno',esc(m.consentDate||'1. 9. 2026'))}${F('Zdroj',esc(m.consentSource||m.source||'Import z Excelu'))}${F('Platnost do',esc(m.consentUntil||fmt(c.consentTo)))}${F('Zaznamenal',esc((user(c.owner)||{}).name||''))}${F('Dokument',doc?`<a href="#/dokumenty/detail/${doc.id}">${esc(doc.title)}</a>`:'<span class="mute">Bez dokumentu</span>')}</div>`);};
